static void storylandRecordProgramAudio(const std::string& message) {
    OutputDebugStringA(("Storyland audio: " + message + "\n").c_str());

    const DWORD required = GetEnvironmentVariableW(L"LOCALAPPDATA", nullptr, 0);
    if (required < 2 || required > 32768) return;

    std::wstring appData(required, L'\0');
    const DWORD copied = GetEnvironmentVariableW(L"LOCALAPPDATA", appData.data(), required);
    if (copied == 0 || copied >= required) return;
    appData.resize(copied);

    std::error_code fileError;
    const std::filesystem::path directory = std::filesystem::path(appData) / L"Storyland";
    std::filesystem::create_directories(directory, fileError);
    if (fileError) return;

    std::ofstream output(directory / L"program_audio.log", std::ios::app);
    if (!output) return;
    SYSTEMTIME time{};
    GetLocalTime(&time);
    output << time.wYear << '-' << time.wMonth << '-' << time.wDay << ' '
           << time.wHour << ':' << time.wMinute << ':' << time.wSecond
           << " | " << message << '\n';
}

static std::filesystem::path storylandAudioOutputPreferencePath(bool createDirectory) {
    const DWORD required=GetEnvironmentVariableW(L"LOCALAPPDATA",nullptr,0);
    if(required<2||required>32768)return {};
    std::wstring directory(required,L'\0');
    const DWORD copied=GetEnvironmentVariableW(L"LOCALAPPDATA",directory.data(),required);
    if(!copied||copied>=required)return {};
    directory.resize(copied);
    const auto folder=std::filesystem::path(directory)/L"Storyland";
    if(createDirectory) {
        std::error_code error;
        std::filesystem::create_directories(folder,error);
        if(error)return {};
    }
    return folder/L"audio_output.ini";
}

static bool storylandAudioDeviceNameWide(const std::string& name,std::wstring& result) {
    result.clear();
    if(name.empty())return true;
    const int count=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,name.data(),int(name.size()),nullptr,0);
    if(count<=0)return false;
    result.resize(size_t(count));
    return MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,name.data(),int(name.size()),result.data(),count)==count;
}

static bool saveStorylandAudioOutputPreference(const std::string& name,std::string& error) {
    const auto path=storylandAudioOutputPreferencePath(true);
    std::wstring wide;
    if(path.empty()||!storylandAudioDeviceNameWide(name,wide)) {
        error="The audio output preference could not be saved.";
        return false;
    }
    std::error_code fileError;
    const bool exists=std::filesystem::exists(path,fileError);
    if(fileError) {
        error="The audio output preference file could not be inspected: "+fileError.message();
        return false;
    }
    if(!exists) {
        std::ofstream preferences(path,std::ios::binary);
        const char marker[]={char(0xFF),char(0xFE)};
        preferences.write(marker,sizeof(marker));
        preferences.close();
        if(!preferences) {
            error="The Unicode audio output preference file could not be created.";
            return false;
        }
    }
    if(!WritePrivateProfileStringW(L"Audio",L"OutputDevice",wide.c_str(),path.c_str())) {
        error="Saving the audio output preference failed (Windows error "+std::to_string(GetLastError())+").";
        return false;
    }
    error.clear();return true;
}

static void storylandSelectAudioMode(StorylandAudioMode mode) {
    mode=storylandAudioModeFromInt(int(mode));
    StorylandAudioMixer::selectAudioMode(mode);
    std::string error;
    if(!saveStorylandAudioOutputPreference(StorylandAudioMixer::preferredOutputDevice(),error)) {
        gStorylandAudioPanelStatus=error;
        storylandRecordProgramAudio(error);
        return;
    }
    const auto path=storylandAudioOutputPreferencePath(true);
    const std::wstring saved=std::to_wstring(int(mode));
    if(path.empty() || !WritePrivateProfileStringW(L"Audio",L"Mode",saved.c_str(),path.c_str())) {
        gStorylandAudioPanelStatus="Audio mode was selected, but the setting could not be saved.";
        storylandRecordProgramAudio(gStorylandAudioPanelStatus);
        return;
    }
    gStorylandAudioPanelStatus=std::string("Audio mode: ")+storylandAudioModeName(mode)+'.';
    storylandRecordProgramAudio(gStorylandAudioPanelStatus);
}

static void loadStorylandAudioOutputPreference() {
    const auto path=storylandAudioOutputPreferencePath(false);
    if(path.empty())return;
    const int savedMode=int(GetPrivateProfileIntW(L"Audio",L"Mode",int(StorylandAudioMode::Ps2),path.c_str()));
    StorylandAudioMixer::selectAudioMode(storylandAudioModeFromInt(savedMode));
    wchar_t name[4096]{};
    const DWORD count=GetPrivateProfileStringW(L"Audio",L"OutputDevice",L"",name,DWORD(std::size(name)),path.c_str());
    if(count>=std::size(name)-1) {
        storylandRecordProgramAudio("Saved audio output name is too long; using Windows default.");
        return;
    }
    const std::string device=storylandWindowsAudio::utf8(std::wstring(name,count));
    std::string error;
    if(!StorylandAudioMixer::selectOutputDevice(device,error))
        storylandRecordProgramAudio("Saved audio output selection failed: "+error);
    else storylandRecordProgramAudio("Preferred audio output: "+(device.empty()?"Windows default":device));
}

static void recordStorylandAudioBuild() {
    std::ostringstream report;
    report<<"Audio build: "<<gStorylandAudioRevision;
    std::wstring executable(32768,L'\0');
    const DWORD count=GetModuleFileNameW(nullptr,executable.data(),DWORD(executable.size()));
    if(count&&count<executable.size()) {
        executable.resize(count);
        report<<"\nExecutable: "<<storylandWindowsAudio::utf8(executable);
        HANDLE file=CreateFileW(executable.c_str(),FILE_READ_ATTRIBUTES,
            FILE_SHARE_READ|FILE_SHARE_WRITE|FILE_SHARE_DELETE,nullptr,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,nullptr);
        if(file!=INVALID_HANDLE_VALUE) {
            FILETIME written{};SYSTEMTIME time{};
            if(GetFileTime(file,nullptr,nullptr,&written)&&FileTimeToSystemTime(&written,&time))
                report<<"\nExecutable modified UTC: "<<time.wYear<<'-'<<time.wMonth<<'-'<<time.wDay<<' '<<
                    time.wHour<<':'<<time.wMinute<<':'<<time.wSecond;
            else report<<"\nExecutable timestamp failed: "<<GetLastError();
            CloseHandle(file);
        } else report<<"\nExecutable attributes failed: "<<GetLastError();
    } else report<<"\nExecutable path failed: "<<GetLastError();
    const HMODULE module=GetModuleHandleW(nullptr);
    const HRSRC resource=module?FindResourceW(module,MAKEINTRESOURCEW(IDR_STORYLAND_INTRO_THEME),L"WAVE"):nullptr;
    report<<"\nEmbedded intro resource 108 bytes: "<<(resource?SizeofResource(module,resource):0);
    if(!resource)report<<" (missing; Windows error "<<GetLastError()<<')';
    gStorylandAudioBuildReport=report.str();
    storylandRecordProgramAudio(gStorylandAudioBuildReport);
}

static void refreshStorylandAudioSessionReport(bool repair) {
    const auto report=repair?storylandWindowsAudio::repairOwnSession():storylandWindowsAudio::inspectOwnSessions();
    gStorylandAudioSessionReport=report.text();
    if(repair) {
        gStorylandAudioPanelStatus=report.repairedSessions?
            "Updated "+std::to_string(report.repairedSessions)+" Storyland audio session(s).":
            "No muted or zero-volume Storyland session was changed.";
        if(!report.errors.empty())gStorylandAudioPanelStatus+=" See the report for Windows errors.";
    }
    storylandRecordProgramAudio(std::string(repair?"Audio session repair: ":"Audio session inspection: ")+
        gStorylandAudioSessionReport);
}

static void openStorylandAudioOutputPanel() {
    gStorylandAudioPanelOpen=true;
    gStorylandAudioPanelMixer=StorylandAudioMixer::current();
    if(!gStorylandAudioPanelMixer) {
        std::string error;
        gStorylandAudioPanelMixer=StorylandAudioMixer::acquire(error);
        if(!gStorylandAudioPanelMixer)gStorylandAudioPanelStatus=error;
    }
    refreshStorylandAudioSessionReport(false);
}

static void selectStorylandAudioOutput(const std::string& name) {
    std::string error;
    if(!StorylandAudioMixer::selectOutputDevice(name,error)) {
        gStorylandAudioPanelStatus="Audio output selection failed: "+error;
        storylandRecordProgramAudio(gStorylandAudioPanelStatus);
        return;
    }
    gStorylandAudioPanelMixer=StorylandAudioMixer::current();
    if(!gStorylandAudioPanelMixer)gStorylandAudioPanelMixer=StorylandAudioMixer::acquire(error);
    if(!gStorylandAudioPanelMixer) {
        gStorylandAudioPanelStatus="Audio output could not be opened: "+error;
        storylandRecordProgramAudio(gStorylandAudioPanelStatus);
        return;
    }
    refreshStorylandAudioSessionReport(true);
    gStorylandAudioPanelStatus="Selected "+(name.empty()?std::string("Windows default"):name)+'.';
    if(!saveStorylandAudioOutputPreference(name,error))gStorylandAudioPanelStatus+=' '+error;
    storylandRecordProgramAudio(gStorylandAudioPanelStatus);
    if(gStorylandAudioPanelMixer)storylandRecordProgramAudio(gStorylandAudioPanelMixer->statusText());
}

static void playStorylandAudioOutputTest() {
    if(gStorylandAudioPanelTest)gStorylandAudioPanelTest->stop();
    auto player=std::make_unique<StorylandProgramAudio>();
    std::wstring error;
    if(!player->playResource(IDR_STORYLAND_INTRO_THEME,false,error)) {
        gStorylandAudioPanelStatus="Test sound could not start: "+storylandWindowsAudio::utf8(error);
        storylandRecordProgramAudio(gStorylandAudioPanelStatus);
        return;
    }
    gStorylandAudioPanelTest=std::move(player);
    refreshStorylandAudioSessionReport(true);
    gStorylandAudioPanelStatus="Playing the embedded Storyland intro once.";
    storylandRecordProgramAudio("Audio test started on "+
        storylandWindowsAudio::utf8(gStorylandAudioPanelTest->outputBackend()));
}

static std::string storylandGameAudioSettingsReport();

static std::string storylandAudioOutputReport() {
    std::string report=gStorylandAudioBuildReport;
    if(gStorylandAudioPanelMixer)report+='\n'+gStorylandAudioPanelMixer->statusText();
    report+='\n'+gStorylandAudioPanelStatus;
    if(gStorylandAudioPanelTest)
        report+="\nTest sound: "+std::string(gStorylandAudioPanelTest->isPlaying()?"playing":"finished")+
            "; playback milliseconds: "+std::to_string(gStorylandAudioPanelTest->playbackMilliseconds())+
            "; backend: "+storylandWindowsAudio::utf8(gStorylandAudioPanelTest->outputBackend());
    report+='\n'+storylandGameAudioSettingsReport();
    report+='\n'+gStorylandAudioSessionReport;
    return report;
}

static bool storylandIsRemembranceDay() {
    SYSTEMTIME localDate{};
    GetLocalTime(&localDate);
    if (localDate.wMonth != 11) return false;
    if (localDate.wDay == 11) return true;
    return localDate.wDay == 12 && localDate.wHour < 12;
}

static std::filesystem::path storylandProgramThemePath(int resourceId,bool introSting) {
    wchar_t executable[MAX_PATH]{};
    if(!GetModuleFileNameW(nullptr,executable,MAX_PATH))return {};
    const auto folder=std::filesystem::path(executable).parent_path();
    const std::wstring name=resourceId==IDR_STORYLAND_INTRO_THEME?L"storyland_intro":
        resourceId==IDR_VCS_ERROR_WARNING_THEME?L"vcs_error_warning_theme":
        resourceId==IDR_GTA3_ERROR_THEME?L"gta3_error_theme":
        resourceId==IDR_GTAVC_ERROR_THEME?L"gtavc_error_theme":
        resourceId==IDR_GTASA_ERROR_THEME?L"gtasa_error_theme":L"reigns_error_theme";
    const std::array<std::wstring,4> extensions={L".wav",L".mp3",L".ogg",L".flac"};
    const std::array<std::filesystem::path,4> directories={
        folder,folder/L"resources",folder/L"music",folder/L"audio"};
    if(introSting) {
        for(const auto& directory:directories) {
            for(const auto& basename:{L"storyland_intro",L"reigns_intro",L"intro_theme"})
                for(const auto& extension:extensions) {
                    const auto candidate=directory/(std::wstring(basename)+extension);
                    std::error_code error;
                    if(std::filesystem::is_regular_file(candidate,error))return candidate;
                }
        }
    }
    for(const auto& directory:directories) {
        for(const auto& extension:extensions) {
            const auto candidate=directory/(name+extension);
            std::error_code error;
            if(std::filesystem::is_regular_file(candidate,error))return candidate;
        }
    }
    return {};
}

static void stopStorylandTheme() {
    if (gStorylandThemeAudio) {
        gStorylandThemeAudio->stop();
        gStorylandThemeAudio.reset();
    }
    if (gStorylandProgramMusic) {
        gStorylandProgramMusic->close();
        gStorylandProgramMusic.reset();
    }
    if (gStorylandThemeUsingPlaySound) {
        PlaySoundW(nullptr, nullptr, 0);
        gStorylandThemeUsingPlaySound = false;
    }
    gStorylandPlayingThemeResource = 0;
}

static std::string narrow(const std::wstring& text);

static bool storylandPlayResourceTheme(int resourceId, bool loop) {
    stopStorylandTheme();
    if (storylandIsRemembranceDay()) return false;
    auto playback = std::make_unique<StorylandProgramAudio>();
    std::wstring error;
    if (playback->playResource(resourceId, loop, error)) {
        gStorylandThemeAudio = std::move(playback);
        gStorylandPlayingThemeResource = resourceId;
        gStorylandProgramMusicStatus = "Playing embedded PCM music using " +
            narrow(gStorylandThemeAudio->outputBackend());
        storylandRecordProgramAudio("Embedded resource " + std::to_string(resourceId) +
            " started on " + gStorylandProgramMusicStatus);
        return true;
    }
    HMODULE module = GetModuleHandleW(nullptr);
    if (module && PlaySoundW(MAKEINTRESOURCEW(resourceId), module,
        SND_RESOURCE | SND_ASYNC | SND_NODEFAULT | (loop ? SND_LOOP : 0))) {
        gStorylandThemeUsingPlaySound = true;
        gStorylandPlayingThemeResource = resourceId;
        gStorylandProgramMusicStatus = "Playing embedded WAV through Windows multimedia";
        storylandRecordProgramAudio("Embedded resource " + std::to_string(resourceId) +
            " started through PlaySound fallback");
        return true;
    }
    gStorylandProgramMusicStatus = "Embedded resource " + std::to_string(resourceId) +
        " could not start: " + narrow(error);
    storylandRecordProgramAudio(gStorylandProgramMusicStatus);
    return false;
}

static bool playStorylandTheme(bool introSting, bool vcsTheme = false) {
    if (storylandIsRemembranceDay()) {
        stopStorylandTheme();
        gStorylandProgramMusicStatus = "Music disabled for Remembrance Day";
        storylandRecordProgramAudio(gStorylandProgramMusicStatus);
        return false;
    }
    const int resourceId = introSting ? IDR_STORYLAND_INTRO_THEME
        : vcsTheme ? IDR_VCS_ERROR_WARNING_THEME : gStorylandErrorThemeResource;
    if (!introSting && gStorylandPlayingThemeResource == resourceId &&
        ((gStorylandThemeAudio && gStorylandThemeAudio->isPlaying()) ||
         (gStorylandProgramMusic && gStorylandProgramMusic->isPlaying()) ||
         gStorylandThemeUsingPlaySound)) return true;

    stopStorylandTheme();
    const auto external = storylandProgramThemePath(resourceId, introSting);
    std::string externalError;
    if (!external.empty()) {
        if (external.extension() == L".wav") {
            auto player = std::make_unique<StorylandProgramAudio>();
            std::wstring error;
            if (player->playFile(external, !introSting, error)) {
                gStorylandThemeAudio = std::move(player);
                gStorylandPlayingThemeResource = resourceId;
                gStorylandProgramMusicStatus = "Playing " + external.filename().string();
                storylandRecordProgramAudio(gStorylandProgramMusicStatus);
                return true;
            }
            externalError = narrow(error);
        }
        // A decoded PCM voice uses the same reliable output path as the
        // embedded WAV resources, including user-supplied MP3 and OGG tracks.
        if (external.extension() != L".wav") {
            auto decoded = std::make_unique<StorylandMediaFile>();
            std::string decodeError;
            if (decoded->loadFromFile(external.wstring(), decodeError) &&
                !decoded->clips().empty()) {
                const auto& clip = decoded->clips().front();
                auto playback = std::make_unique<StorylandProgramAudio>();
                std::wstring outputError;
                if (playback->playPcm16(clip.pcm.data(), clip.pcm.size(),
                    clip.sampleRate, clip.channels, !introSting, outputError)) {
                    gStorylandThemeAudio = std::move(playback);
                    gStorylandPlayingThemeResource = resourceId;
                    gStorylandProgramMusicStatus = "Playing decoded audio " + external.filename().string();
                    storylandRecordProgramAudio(gStorylandProgramMusicStatus);
                    return true;
                }
                externalError = narrow(outputError);
            } else if (!decodeError.empty()) externalError = decodeError;
        }
        auto player = std::make_unique<StorylandMediaFile>();
        std::string error;
        if (player->loadRadioStream(external.wstring(), error)) {
            player->setPlaybackLooping(!introSting);
            if (player->play(error)) {
                gStorylandProgramMusic = std::move(player);
                gStorylandPlayingThemeResource = resourceId;
                gStorylandProgramMusicStatus = "Playing " + external.filename().string();
                storylandRecordProgramAudio(gStorylandProgramMusicStatus);
                return true;
            }
        }
        if (!error.empty()) externalError = error;
        if (external.extension() == L".wav" && PlaySoundW(external.c_str(), nullptr,
            SND_FILENAME | SND_ASYNC | SND_NODEFAULT | (!introSting ? SND_LOOP : 0))) {
            gStorylandThemeUsingPlaySound = true;
            gStorylandPlayingThemeResource = resourceId;
            gStorylandProgramMusicStatus = "Playing WAV " + external.filename().string();
            storylandRecordProgramAudio(gStorylandProgramMusicStatus);
            return true;
        }
    }
    if (storylandPlayResourceTheme(resourceId, !introSting)) return true;
    if (!externalError.empty()) {
        gStorylandProgramMusicStatus += "; external media failed: " + externalError;
        storylandRecordProgramAudio(gStorylandProgramMusicStatus);
    }
    return false;
}

static int storylandMessageBoxW(HWND owner, LPCWSTR text, LPCWSTR caption, UINT type) {
    const bool isError = (type & MB_ICONERROR) == MB_ICONERROR;
    const bool isWarning = (type & MB_ICONWARNING) == MB_ICONWARNING;

    if (gStorylandVcsThemeContext && (isError || isWarning)) {
        // VCS warnings and errors use the VCS-specific user-supplied 8-bit theme.
        // Restarting it here also covers catastrophic errors while a VCS file is
        // the active context.
        playStorylandTheme(false, true);
    } else if (isError || isWarning) {
        // Use the active game theme; unknown and Leeds contexts retain Reigns.
        playStorylandTheme(false, false);
    }

    const int result = ::MessageBoxW(owner, text, caption, type);
    if (isError || isWarning) stopStorylandTheme();
    return result;
}

