static void loadCtwRenderTimecycle() {
    gCtwRenderTimecycle = {};
    gCtwRenderTimecycleError.clear();
    if (gCtwPakFile.header().mobile) return;
    const auto directory = gCtwPakFile.sourcePath().parent_path();
    storyland_ctw::WadArchive wad;
    std::error_code ec;
    auto toc = directory / "ROM.TOC";
    if (!std::filesystem::exists(toc, ec)) toc = directory / "rom.toc";
    if (!std::filesystem::exists(toc, ec)) {
        gCtwRenderTimecycleError = "Place ROM.TOC and ROM.WAD beside GAME.PAK to use the PSP timecycle.";
        return;
    }
    if (!wad.loadFromFile(toc, gCtwRenderTimecycleError)) return;
    for (size_t index = 0; index < wad.resources().size(); ++index) {
        if (wad.resources()[index].hash != storyland_ctw::PspTimecycle::ResourceHash) continue;
        std::vector<uint8_t> bytes;
        if (wad.extractResource(index, bytes, gCtwRenderTimecycleError))
            gCtwRenderTimecycle.load(bytes, gCtwRenderTimecycleError);
        return;
    }
    gCtwRenderTimecycleError = "ROM.WAD has no PSP timecycle resource.";
}
