static UINT storylandSelectedShaderCommand() {
    if(gStorylandPcShaderEnabled)return StorylandPcShaderCommand;
    if(gSanAndreasEnabled)return 49998;
    if(gMafia2Enabled)return 49999;
    if(gCelEnabled)return 50189;
    if(gBudokaiEnabled)return 50190;
    if(gMobileEnabled)return 49991;
    if(gCtwStoriesEnabled)return 49988;
    if(gNeoEnabled)return 49989;
    if(gAeroEnabled)return UINT(49994+std::clamp(gAeroQuality,0,3));
    if(gStoriesConsoleFollowsGame)return ID_VIEW_RENDER_STORIES;
    constexpr std::array<UINT,4> commands{{49986,49987,49992,49993}};
    if(gStoriesConsoleProfile>=0&&gStoriesConsoleProfile<int(commands.size()))
        return commands[size_t(gStoriesConsoleProfile)];
    return ID_VIEW_RENDER_STORIES;
}
static void drawStorylandShaderSelection() {
    constexpr std::array<UINT,17> commands{{
        ID_VIEW_RENDER_STORIES,49998,49986,49987,49992,StorylandPcShaderCommand,49993,
        49988,49991,49989,50189,50190,49999,49994,49995,49996,49997
    }};
    constexpr std::array<const char*,17> names{{
        "Default","San Andreas","LCS PS2","LCS PSP","VCS PS2","PC","VCS PSP",
        "CTW PSP","Mobile","Neo (SkyGFX)","Cel","Budokai 1","Mafia 2",
        "Aero Low","Aero Medium (Phong)","Aero High (Blinn-Phong)","Aero Ultra High (Blinn-Phong)"
    }};
    const UINT command=storylandSelectedShaderCommand();
    int selected=0;
    for(size_t index=0;index<commands.size();++index)
        if(commands[index]==command)selected=int(index);
    if(ImGui::Combo("Shader profile",&selected,names.data(),int(names.size())))
        PostMessageW(gMainWindow,WM_COMMAND,commands[size_t(selected)],0);
}
