static bool storylandMouseInGameView(HWND window) {
    POINT point{};RECT bounds{};
    if(!GetCursorPos(&point)||!ScreenToClient(window,&point)||!GetClientRect(window,&bounds))return false;
    return storylandGameView(int(bounds.right-bounds.left),int(bounds.bottom-bounds.top)).contains(float(point.x),float(point.y));
}
static bool gStorylandPcAimMouseActive=false;
static POINT gStorylandPcAimMouseRestore{};
static POINT gStorylandPcAimMouseCenter{};
static void storylandReadPcAimMouse(HWND window,bool enabled,StorylandPlayTestCameraInput& input) {
    if(!enabled) {
        if(!gStorylandPcAimMouseActive)return;
        gStorylandPcAimMouseActive=false;
        if(GetCapture()==window)ReleaseCapture();
        ShowCursor(TRUE);
        if(GetForegroundWindow()==GetAncestor(window,GA_ROOT))
            SetCursorPos(gStorylandPcAimMouseRestore.x,gStorylandPcAimMouseRestore.y);
        return;
    }
    POINT pointer{};RECT bounds{};
    if(!GetCursorPos(&pointer)||!GetClientRect(window,&bounds))return;
    const auto view=storylandGameView(int(bounds.right-bounds.left),int(bounds.bottom-bounds.top));
    if(view.width<=0||view.height<=0)return;
    POINT center{view.x+view.width/2,view.y+view.height/2};
    if(!ClientToScreen(window,&center))return;
    if(!gStorylandPcAimMouseActive) {
        gStorylandPcAimMouseRestore=pointer;gStorylandPcAimMouseActive=true;
        SetCapture(window);ShowCursor(FALSE);
    } else {
        input.yawDelta=-float(pointer.x-gStorylandPcAimMouseCenter.x)*.16f;
        input.pitchDelta=float(pointer.y-gStorylandPcAimMouseCenter.y)*.16f;
    }
    gStorylandPcAimMouseCenter=center;
    SetCursorPos(center.x,center.y);
}
