static void syncStorylandConsoleLighting() {
    if(gStorylandPcShaderEnabled) {
        gStoriesConsoleFollowsGame=false;
        gStoriesConsoleProfile=storylandShaderRenderProfile(StorylandPcShaderProfile);
    }
    if(gStoriesConsoleFollowsGame&&gStoriesConsoleProfile>=0&&!gDtzArchive.unpackedBytes().empty()) {
        gStoriesConsoleProfile=(gDtzArchive.gameVariant()==StorylandDtzGameVariant::Vcs?2:0)+
            (gDtzArchive.isPsp()?1:0);
    }
    gStoriesSky.setPspLighting(gStoriesConsoleProfile==3);
    if(gPs2EnvironmentProfile!=gStoriesConsoleProfile)gPs2EnvironmentReady=false;
    gPlayTestHudAssets.setPcMode(gStorylandPcShaderEnabled);
}

static void updateStorylandSkyFrame(double now) {
    syncStorylandConsoleLighting();
    const double elapsed = gStoriesSkyLastTick > 0 ? now - gStoriesSkyLastTick : 0;
    gStoriesSkyLastTick = now;
    gStoriesSky.update(float(std::clamp(elapsed, 0.0, 0.25)));
}

