static bool refreshStorylandNativeScenery(std::string& error) {
    auto scenery=std::make_unique<StorylandArchiveBrowser>();
    StorylandNativeSceneryReport report;
    if(!scenery->loadNativeScenery(gDtzArchive,report,error)) {
        error="Vegetation and objects: "+error;
        return false;
    }
    if(!storylandApplyNativeObjectVisibility(*scenery,gDtzArchive,
        gPlayTestMissionEnvironment.invisibleNativeObjects,error))return false;
    StorylandArchiveBrowser* existing=gArchiveBrowser.hasNativeScenery()?&gArchiveBrowser:nullptr;
    for(auto& area:gAreaArchives)if(area.browser&&area.browser->hasNativeScenery()) {
        existing=area.browser.get();
        area.loadError.clear();
        break;
    }
    if(existing)*existing=std::move(*scenery);
    else {
        auto area=std::find_if(gAreaArchives.begin(),gAreaArchives.end(),
            [](const auto& item) {return item.name==L"Vegetation and objects";});
        if(area==gAreaArchives.end()) {
            StorylandAreaArchive added;
            added.name=L"Vegetation and objects";
            added.browser=std::move(scenery);
            gAreaArchives.push_back(std::move(added));
        } else {
            area->browser=std::move(scenery);
            area->loadError.clear();
        }
    }
    gNativeSceneryReport=std::move(report);
    gNativeSceneryNeedsRefresh=false;
    gNativeSceneryStatus=widen(gNativeSceneryReport.summary());
    ++gDtzWorldTextureGeneration;
    const auto log=storylandUserFilesDirectory(
        gDtzArchive.gameVariant()==StorylandDtzGameVariant::Vcs)/L"Storyland-Scenery.log";
    if(!storylandSaveSceneryReport(gNativeSceneryReport,gDtzArchive.companionImgPath(),log))
        gNativeSceneryStatus+=L"; could not write Storyland-Scenery.log";
    error.clear();
    return true;
}

static bool resetStorylandBuildingSwaps() {
    gDtzArchive.bindScriptCollisionWorld(nullptr);
    const bool modelsChanged=std::any_of(gDtzArchive.nativeWorld().instances.begin(),
        gDtzArchive.nativeWorld().instances.end(),[](const auto& instance) {
            return instance.modelId!=instance.originalModelId;
        });
    gDtzArchive.resetBuildingSwaps();
    storylandDisableEscalators(gPlayTestRuntime.escalators,gDtzArchive.nativeWorld());
    gDtzArchive.setFortStauntonDestroyed(false);
    gDtzArchive.resetCollisionStreaming();
    gArchiveBrowser.resetBuildingSwaps();
    for(auto& area:gAreaArchives)if(area.browser)area.browser->resetBuildingSwaps();
    gPlayTestMissionEnvironment.buildingModelSwaps.clear();
    gPlayTestMissionEnvironment.buildingModelSwapsChanged=false;
    gPlayTestMissionEnvironment.buildingSwapCommands.clear();
    gPlayTestMissionEnvironment.invisibleNativeObjects.clear();
    gPlayTestMissionEnvironment.nativeObjectVisibilityChanged=false;
    gNativeSceneryNeedsRefresh=gNativeSceneryNeedsRefresh||modelsChanged;
    gBuildingSwapsApplied=gNativeSceneryNeedsRefresh;
    if(gNativeSceneryNeedsRefresh) {
        std::string error;
        if(!refreshStorylandNativeScenery(error)) {
            gPlayTestMissionVm.state=StorylandMissionState::Unsupported;
            gPlayTestMissionVm.diagnostic=error;
            gNativeSceneryStatus=widen(error);
            return false;
        }
    }
    gBuildingSwapsApplied=false;
    synchronizeStorylandNativeScenery();
    return true;
}

static bool loadStorylandPlayTestScene(const std::array<float,3>& point,std::string& error);

static bool applyStorylandBuildingModelSwap(uint64_t worldKey,
    const StorylandMissionEnvironment::BuildingModelSwap& swap,bool& changed,std::string& error) {
    // PS2 LCS stores collision model identities separately from compiled render
    // instances. 03BB changes this native building; 0635 selects the matching
    // precompiled visual variant through the LVZ swap-slot tables.
    changed=false;
    const auto& instances=gDtzArchive.nativeWorld().instances;
    const auto instance=std::find_if(instances.begin(),instances.end(),[&](const auto& item) {
        return ((uint64_t(item.poolHeader)<<32)|item.poolIndex)==worldKey;
    });
    if(instance!=instances.end()&&instance->modelId==swap.replacementModel)return true;
    if(!gDtzArchive.replaceBuildingModel(worldKey,swap.replacementModel)) {
        error="Building swap references an unavailable native instance.";return false;
    }
    changed=true;
    gNativeSceneryNeedsRefresh=true;
    gBuildingSwapsApplied=true;
    return true;
}

static bool applyStorylandBuildingSwaps() {
    auto& world=gPlayTestMissionEnvironment;
    const auto failure=[](const std::string& error) {
        gPlayTestMissionVm.state=StorylandMissionState::Unsupported;
        gPlayTestMissionVm.diagnostic=error;
        return false;
    };
    if(world.buildingModelSwapsChanged) {
        for(const auto& entry:world.buildingModelSwaps) {
            std::string error;
            bool changed=false;
            if(!applyStorylandBuildingModelSwap(entry.first,entry.second,changed,error))return failure(error);
        }
        world.buildingModelSwapsChanged=false;
    }
    auto& commands=gPlayTestMissionEnvironment.buildingSwapCommands;
    if(!commands.empty())gBuildingSwapsApplied=true;
    for(const auto& command:commands) {
        const auto apply=[&](StorylandArchiveBrowser& browser) {
            if(command.group)browser.setBuildingSwapGroup(command.key,command.state);
            else {
                browser.setBuildingSwap(command.key,command.state);
                if(gDtzArchive.applyBuildingSwaps(browser.buildingSwaps(),
                    {{command.key,int32_t(command.state)}})!=0) {
                    gNativeSceneryNeedsRefresh=true;
                }
            }
        };
        apply(gArchiveBrowser);
        for(auto& area:gAreaArchives)if(area.browser)apply(*area.browser);
    }
    commands.clear();
    const bool refresh=gNativeSceneryNeedsRefresh;
    if(refresh) {
        std::string error;
        if(!refreshStorylandNativeScenery(error))return failure(error);
        world.nativeObjectVisibilityChanged=true;
    }
    if(refresh||world.nativeObjectVisibilityChanged) {
        gBuildingSwapsApplied=true;
        const auto applyVisibility=[&](StorylandArchiveBrowser& browser) {
            std::string error;
            if(!storylandApplyNativeObjectVisibility(browser,gDtzArchive,world.invisibleNativeObjects,error))
                return failure(error);
            return true;
        };
        if(!applyVisibility(gArchiveBrowser))return false;
        for(auto& area:gAreaArchives)if(area.browser&&!applyVisibility(*area.browser))return false;
        world.nativeObjectVisibilityChanged=false;
    }
    return true;
}

