static LPARAM addTreePayload(StorylandTreeKind kind, int index) {
    gTreePayloads.push_back({kind, index});
    return LPARAM(gTreePayloads.size());
}

static StorylandTreePayload payloadFromLParam(LPARAM value) {
    if (value <= 0) return {};
    size_t index = size_t(value - 1);
    if (index >= gTreePayloads.size()) return {};
    return gTreePayloads[index];
}

static HTREEITEM addTreeItem(HTREEITEM parent, const std::wstring& text, StorylandTreeKind kind = StorylandTreeKind::None, int index = -1) {
    TVINSERTSTRUCTW insert = {};
    insert.hParent = parent;
    insert.hInsertAfter = TVI_LAST;
    insert.item.mask = TVIF_TEXT | TVIF_PARAM;
    insert.item.pszText = const_cast<LPWSTR>(text.c_str());
    insert.item.lParam = addTreePayload(kind, index);
    return reinterpret_cast<HTREEITEM>(SendMessageW(gTree, TVM_INSERTITEMW, 0, reinterpret_cast<LPARAM>(&insert)));
}

class StorylandResourceTreeBuild {
public:
    using Item = size_t;
    static constexpr Item root = SIZE_MAX;

    explicit StorylandResourceTreeBuild(HWND target) : window(target) {
        if (window) SendMessageW(window, WM_SETREDRAW, FALSE, 0);
    }

    ~StorylandResourceTreeBuild() {
        if (window) {
            SendMessageW(window, WM_SETREDRAW, TRUE, 0);
            InvalidateRect(window, nullptr, TRUE);
        }
    }

    Item add(Item parent, const std::wstring& text, StorylandTreeKind kind, int index) {
        const Item item = nodes.size();
        const Item previous = parent == root ? firstRoot : nodes[parent].firstChild;
        nodes.push_back({text, addTreePayload(kind, index), root, previous, nullptr});
        if (parent == root) firstRoot = item;
        else nodes[parent].firstChild = item;
        return item;
    }

    void expand(Item item) {
        if (item != root) expandedItems.push_back(item);
    }

    void commit() {
        // Insert reversed sibling lists at the front to retain the original order.
        insertChildren(TVI_ROOT, firstRoot);
        for (const auto& node : nodes) insertChildren(node.handle, node.firstChild);
        for (Item item : expandedItems) {
            if (nodes[item].handle)
                SendMessageW(window, TVM_EXPAND, TVE_EXPAND, reinterpret_cast<LPARAM>(nodes[item].handle));
        }
    }

private:
    struct Node {
        std::wstring text;
        LPARAM payload;
        Item firstChild;
        Item nextSibling;
        HTREEITEM handle;
    };
    HWND window;
    Item firstRoot = root;
    std::vector<Node> nodes;
    std::vector<Item> expandedItems;

    void insertChildren(HTREEITEM parent, Item child) {
        while (child != root) {
            auto& node = nodes[child];
            TVINSERTSTRUCTW insert = {};
            insert.hParent = parent;
            insert.hInsertAfter = TVI_FIRST;
            insert.item.mask = TVIF_TEXT | TVIF_PARAM;
            insert.item.pszText = const_cast<LPWSTR>(node.text.c_str());
            insert.item.lParam = node.payload;
            node.handle = reinterpret_cast<HTREEITEM>(SendMessageW(
                window, TVM_INSERTITEMW, 0, reinterpret_cast<LPARAM>(&insert)));
            child = node.nextSibling;
        }
    }
};

