static bool loadWorldGameContext(std::string& error) {
    if (gMode == StorylandMode::ArchiveFile) {
        std::wstring dtzPath;
        const std::wstring worldPath = !gArchiveBrowser.lvzPath().empty() ? gArchiveBrowser.lvzPath() : gArchiveBrowser.imgPath();
        if (!storylandFindPlayTestDtz(worldPath, dtzPath, error) || !gDtzArchive.loadFromFile(dtzPath, error)) return false;
        applyStorylandTitleTint(storiesDtzTint());
        std::string timecycleError;
        gStoriesSky.loadNativeTimecycle(gDtzArchive.unpackedBytes(),gDtzArchive.gameVariant()==StorylandDtzGameVariant::Vcs,timecycleError);
    }
    if (!gDtzArchive.hasCompanionImg()) {
        error = "Open GAME.DTZ with its matching gta3PS2/gta3PSP IMG to load the native paths and zone collision archives.";
        return false;
    }
    return true;
}

static float storylandPlayTestMusicFadeGain() {
    const auto& world=gPlayTestMissionEnvironment;
    return world.musicDoesFade?1.0f-std::clamp(world.fadeAlpha,0.0f,1.0f):1.0f;
}
static void stopStorylandMissionPassedTune(bool restoreMusic=false) {
    const bool active=bool(gPlayTestMissionPassedTune);
    if(gPlayTestMissionPassedTune)gPlayTestMissionPassedTune->cancelled=true;
    gPlayTestMissionPassedTune.reset();gPlayTestMissionTuneStream=-1;
    auto& world=gPlayTestMissionEnvironment;
    // Native completion playback returns to game music after its frontend track ends.
    if(active&&restoreMusic&&!gPlayTestMissionVm.vcs&&world.scriptAudioMode==0) {
        world.scriptAudioMode=1;
        world.radioEnabled=true;
        world.radioChanged=true;
    }
}
static bool playStorylandLcsMissionPassedTune(int32_t selector,std::string& error) {
    if(gPlayTestMissionVm.vcs||selector!=1) {
        error="Mission completion music requires the verified LCS tune selector 1.";
        return false;
    }
    if(gPlayTestMissionPassedTune&&!gPlayTestMissionPassedTune->finished) {error.clear();return true;}
    // LCS STREAMED_SOUND_MISSION_COMPLETED is AUDIO/MUSIC/MISCOM2.
    std::wstring selected;
    bool nativeStream=false;
    for(const auto& asset:gPlayTestRetailAssets.files) {
        if(asset.group!="Audio"||asset.bytes==0)continue;
        const auto path=std::filesystem::path(asset.path);
        auto name=path.stem().wstring(),extension=path.extension().wstring();
        const auto lower=[](wchar_t value){return wchar_t(std::towlower(value));};
        std::transform(name.begin(),name.end(),name.begin(),lower);
        std::transform(extension.begin(),extension.end(),extension.begin(),lower);
        if(name!=L"miscom2")continue;
        if(extension!=L".vb"&&extension!=L".at3"&&extension!=L".aa3"&&extension!=L".oma"&&
            extension!=L".wav"&&extension!=L".mp3"&&extension!=L".ogg"&&extension!=L".flac")continue;
        if(selected.empty()||(!nativeStream&&extension==L".vb")) {
            selected=asset.path;
            nativeStream=extension==L".vb";
        }
    }
    if(selected.empty()) {
        error="PLAY_MISSION_PASSED_TUNE requires the LCS AUDIO/MUSIC/MISCOM2 stream.";
        return false;
    }
    auto ticket=gPlayTestGameAudio.submit(selected,0,false,gPlayTestRuntime.sounds?1.0f:0.0f,true,false,false,
        StorylandFrontendAmbience::MissionPassed);
    if(ticket->failed) {
        error="Mission completion music: "+ticket->diagnostic;
        return false;
    }
    stopStorylandMissionPassedTune(false);
    gPlayTestMissionPassedTune=std::move(ticket);
    gPlayTestMissionEnvironment.scriptAudioMode=0;
    gPlayTestMissionEnvironment.radioEnabled=false;
    gPlayTestMissionEnvironment.radioChanged=true;
    error.clear();
    return true;
}
static bool playStorylandMissionPassedTune(int32_t stream,bool looping,std::string& error) {
    const char* stem=gPlayTestMissionVm.vcs?storylandVcsMusicStreamStem(stream):storylandLcsMusicStreamStem(stream);
    if(!stem) {error="Mission completion stream is outside the native table.";return false;}
    std::wstring selected;bool nativeStream=false;
    for(const auto& asset:gPlayTestRetailAssets.files) {
        if(asset.group!="Audio"||!asset.bytes)continue;
        const auto path=std::filesystem::path(asset.path);
        auto name=path.stem().string(),extension=path.extension().string();
        const auto lower=[](unsigned char value){return char(std::tolower(value));};
        std::transform(name.begin(),name.end(),name.begin(),lower);
        std::transform(extension.begin(),extension.end(),extension.begin(),lower);
        if(name!=stem)continue;
        if(extension!=".vb"&&extension!=".at3"&&extension!=".aa3"&&extension!=".oma"&&extension!=".wav"&&
            extension!=".mp3"&&extension!=".ogg"&&extension!=".flac")continue;
        if(selected.empty()||(!nativeStream&&extension==".vb")) {selected=asset.path;nativeStream=extension==".vb";}
    }
    if(selected.empty()) {error="Mission completion music requires the retail stream: "+std::string(stem);return false;}
    auto ticket=gPlayTestGameAudio.submit(selected,0,false,gPlayTestRuntime.sounds?storylandPlayTestMusicFadeGain():0,true,looping,false,
        std::string(stem)=="miscom2"?StorylandFrontendAmbience::MissionPassed:StorylandFrontendAmbience::None);
    if(ticket->failed) {error="Mission completion music: "+ticket->diagnostic;return false;}
    stopStorylandMissionPassedTune();
    gPlayTestMissionPassedTune=std::move(ticket);gPlayTestMissionTuneStream=stream;
    gPlayTestMissionTuneSerial=gPlayTestMissionEnvironment.missionPassedTuneSerial+1;
    error.clear();return true;
}
static void updateStorylandMissionPassedTune() {
    if(!gPlayTestMissionVm.vcs) {
        auto& world=gPlayTestMissionEnvironment;
        if(gPlayTestActive&&!gPlayTestMissionPassedTune&&world.lcsExtendedWorld.musicPlaying) {
            std::string error;
            if(!playStorylandMissionPassedTune(world.lcsExtendedWorld.musicTrack,
                world.lcsExtendedWorld.musicLooped,error))gPlayTestSoundStatus=error;
            else world.scriptAudioMode=0;
        }
        if(!gPlayTestMissionPassedTune)return;
        if(!gPlayTestActive||gPlayTestMissionVm.vcs||gPlayTestMissionEnvironment.scriptAudioMode!=0) {
            stopStorylandMissionPassedTune(false);
            return;
        }
        auto& ticket=*gPlayTestMissionPassedTune;
        ticket.paused=gPlayTestRuntime.paused||gPlayTestRuntime.pauseMenu||gPlayTestDebugMenuOpen;
        ticket.gain=gPlayTestRuntime.sounds?gStorylandSfxVolume:0.0f;
        if(ticket.failed)gPlayTestSoundStatus="Mission completion music: "+ticket.diagnostic;
        if(ticket.finished) {
            world.lcsExtendedWorld.musicPlaying=false;
            world.missionPassedTune=-1;world.missionTuneLoop=false;
            stopStorylandMissionPassedTune(true);
        }
        return;
    }
    auto& world=gPlayTestMissionEnvironment;
    if(!gPlayTestActive||world.missionPassedTune<0) {stopStorylandMissionPassedTune();return;}
    if(!gPlayTestMissionPassedTune&&gPlayTestMissionTuneSerial!=world.missionPassedTuneSerial) {
        std::string error;
        if(!playStorylandMissionPassedTune(world.missionPassedTune,world.missionTuneLoop,error))gPlayTestSoundStatus=error;
        gPlayTestMissionTuneSerial=world.missionPassedTuneSerial;
    }
    if(!gPlayTestMissionPassedTune)return;
    auto& ticket=*gPlayTestMissionPassedTune;
    ticket.paused=gPlayTestRuntime.paused||gPlayTestRuntime.pauseMenu||gPlayTestDebugMenuOpen;
    ticket.gain=gPlayTestRuntime.sounds&&world.frontendAudioEnabled?gStorylandMusicVolume*storylandPlayTestMusicFadeGain():0;
    if(ticket.failed)gPlayTestSoundStatus="Mission completion music: "+ticket.diagnostic;
    if(ticket.finished) {stopStorylandMissionPassedTune();world.missionPassedTune=-1;world.missionTuneLoop=false;}
}
static void refreshStorylandClearedActorPresentation(size_t previousCars,size_t previousPedestrians) {
    if(gNativeVehicles.size()<previousCars) {
        const int32_t occupied=gPlayTestRuntime.occupiedVehicle;
        if(occupied>=0&&size_t(occupied)<gNativeVehicles.size()&&
            size_t(occupied)<gPlayTestRuntime.vehicles.size())gPlayTestRadioVehicle=occupied;
        else {
            gPlayTestRadioVehicle=-1;
            gPlayTestRadioWasDriving=false;
        }
        for(auto& voice:gPlayTestEngines) {
            for(auto& player:voice.players) {
                if(player)player->cancelled=true;
                player.reset();
            }
            voice.vehicle=-1;
        }
    }
    if(gNativePedestrians.size()<previousPedestrians) {
        gPlayTestPedestrianBlends.assign(gNativePedestrians.size(),{});
        gPlayTestPedShotSeen.resize(gNativePedestrians.size());
        for(size_t index=0;index<gNativePedestrians.size()&&index<gPlayTestRuntime.pedestrians.size();++index)
            gPlayTestPedShotSeen[index]=gPlayTestRuntime.pedestrians[index].shotSerial;
    }
}

