    for(auto& entry:gPlayTestPoliceHeliVoices)if(entry.second.ticket)entry.second.ticket->cancelled=true;
    gPlayTestPoliceHeliVoices.clear();
    for(auto& ticket:gPlayTestWaterCannonTickets) {if(ticket)ticket->cancelled=true;ticket.reset();}
    gPlayTestLcsScriptSpeech.clear();
    if(gPlayTestPoliceRadioTicket)gPlayTestPoliceRadioTicket->cancelled=true;
    gPlayTestPoliceRadioTicket.reset();gPlayTestPoliceRadioQueue.clear();
    stopStorylandMissionPassedTune(true);gPlayTestMissionTuneSerial=UINT32_MAX;
    for(auto& voice:gPlayTestContinuousVoices)if(voice.second.ticket)voice.second.ticket->cancelled=true;
    gPlayTestContinuousVoices.clear();
    for(auto& voice:gPlayTestEngines) {
        for(auto& player:voice.players) {if(player)player->cancelled=true;player.reset();}
        voice.vehicle=-1;
    }
    for(auto& ticket:gPlayTestSpeechTickets) {if(ticket)ticket->cancelled=true;ticket.reset();}
    gPlayTestSpeechStates.clear();gPlayTestSpeechTickets.clear();gPlayTestSpeechIdentities.clear();
    for(auto& entry:gPlayTestMissionSpeechTickets)if(entry.second)entry.second->cancelled=true;
    gPlayTestMissionSpeechTickets.clear();gPlayTestMissionSpeechStates.clear();
    gPlayTestMissionSpeechIdentities.clear();
    gPlayTestCharacterSpeechGlobal={};gPlayTestCharacterSpeechCamera={};
    gPlayTestConversationA=gPlayTestConversationB=gPlayTestConversationSpeaker=-1;
    for(auto& ticket:gPlayTestSoundTickets) {if(ticket)ticket->cancelled=true;ticket.reset();}
    for(auto& ticket:gPlayTestMissionTickets) {if(ticket)ticket->cancelled=true;ticket.reset();}
    if(gPlayTestNativeCutsceneAudio)gPlayTestNativeCutsceneAudio->cancelled=true;
    gPlayTestNativeCutsceneAudio.reset();
    gPlayTestNativeCutsceneAudioLoad=gPlayTestNativeCutsceneAudioClear=gPlayTestNativeCutsceneAudioStart=0;
    gPlayTestCutsceneMillisecondRemainder=0.0;
