static void drawStorylandDearImGuiMenuItems(HMENU menu) {
    if (!menu) return;
    if(menu==gTimeMenu)updateStorylandTimeMenuChecks();
    const int count = GetMenuItemCount(menu);
    for (int index = 0; index < count; ++index) {
        MENUITEMINFOW item{};
        wchar_t label[256]{};
        item.cbSize = sizeof(item);
        item.fMask = MIIM_FTYPE | MIIM_STATE | MIIM_ID | MIIM_SUBMENU | MIIM_STRING;
        item.dwTypeData = label;
        item.cch = 255;
        if (!GetMenuItemInfoW(menu, UINT(index), TRUE, &item)) continue;
        if (item.fType & MFT_SEPARATOR) {
            ImGui::Separator();
            continue;
        }
        std::string title = narrow(label);
        const size_t mnemonic = title.find('&');
        if (mnemonic != std::string::npos) title.erase(mnemonic, 1);
        const size_t shortcut = title.find('\t');
        if (shortcut != std::string::npos) title.resize(shortcut);
        const bool enabled = (item.fState & (MFS_DISABLED | MFS_GRAYED)) == 0;
        if (item.hSubMenu) {
            if (ImGui::BeginMenu(title.c_str(), enabled)) {
                drawStorylandDearImGuiMenuItems(item.hSubMenu);
                ImGui::EndMenu();
            }
        } else if (ImGui::MenuItem(title.c_str(), nullptr, (item.fState & MFS_CHECKED) != 0, enabled)) {
            PostMessageW(gMainWindow, WM_COMMAND, item.wID, 0);
        }
    }
}

static void drawStorylandDearImGuiTree(HTREEITEM item, int depth = 0) {
    if (!gTree || depth > 32) return;
    while (item) {
        TVITEMW entry{};
        wchar_t label[512]{};
        entry.mask = TVIF_TEXT | TVIF_PARAM | TVIF_STATE;
        entry.stateMask = TVIS_EXPANDED;
        entry.hItem = item;
        entry.pszText = label;
        entry.cchTextMax = 511;
        HTREEITEM next = TreeView_GetNextSibling(gTree, item);
        if (getStorylandTreeItem(entry)) {
            HTREEITEM child = TreeView_GetChild(gTree, item);
            const bool selected = TreeView_GetSelection(gTree) == item;
            ImGui::PushID(static_cast<int>(reinterpret_cast<UINT_PTR>(item) & 0x7FFFFFFFu));
            const ImGuiTreeNodeFlags flags = (child ? ImGuiTreeNodeFlags_OpenOnArrow |
                ImGuiTreeNodeFlags_SpanAvailWidth : ImGuiTreeNodeFlags_Leaf |
                ImGuiTreeNodeFlags_NoTreePushOnOpen | ImGuiTreeNodeFlags_SpanAvailWidth) |
                (selected ? ImGuiTreeNodeFlags_Selected : 0);
            if ((entry.state & TVIS_EXPANDED) && child) ImGui::SetNextItemOpen(true, ImGuiCond_Once);
            const bool open = ImGui::TreeNodeEx(narrow(label).c_str(), flags);
            if (ImGui::IsItemClicked() && !ImGui::IsItemToggledOpen()) {
                gDearImGuiTreeSelectionChanged = true;
                TreeView_SelectItem(gTree, item);
                if (gPreview) InvalidateRect(gPreview, nullptr, FALSE);
            }
            if (ImGui::BeginPopupContextItem("##resourceActions")) {
                if (TreeView_GetSelection(gTree) != item) {
                    gDearImGuiTreeSelectionChanged = true;
                    TreeView_SelectItem(gTree, item);
                }
                HMENU context = CreatePopupMenu();
                if (context) {
                    if (buildTreeContextMenu(context)) drawStorylandDearImGuiMenuItems(context);
                    DestroyMenu(context);
                }
                ImGui::EndPopup();
            }
            if (child) {
                if (open) drawStorylandDearImGuiTree(child, depth + 1);
                if (open) ImGui::TreePop();
            }
            ImGui::PopID();
        }
        if (gDearImGuiTreeSelectionChanged) return;
        item = next;
    }
}

struct StorylandPanelLayout {
    bool maximized = false;
    bool restorePending = false;
    ImVec2 position{}, size{};
    ImGuiID dockId = 0;
};
static StorylandPanelLayout gDetailsPanelLayout, gActionsPanelLayout, gPlayTestPanelLayout;

// Keep the ordinary floating/docked placement when switching to a large view.
// The viewport is queried each frame so a maximized panel follows window resizing.
static bool beginStorylandPanel(const char* title, bool* open, ImVec2 position,
    ImVec2 size, StorylandPanelLayout& layout, bool fixedPane = false) {
    ImGui::SetNextWindowPos(position, (fixedPane || gResetPanelLayout) ? ImGuiCond_Always : ImGuiCond_FirstUseEver);
    ImGui::SetNextWindowSize(size, (fixedPane || gResetPanelLayout) ? ImGuiCond_Always : ImGuiCond_FirstUseEver);
    if (gResetPanelLayout) { layout = {}; ImGui::SetNextWindowDockID(0); }
    if (fixedPane) {
        ImGui::SetNextWindowDockID(0);
        layout.maximized = false;
        layout.restorePending = false;
        return ImGui::Begin(title, open, ImGuiWindowFlags_NoMove |
            ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoDocking);
    }
    if (layout.maximized) {
        const ImGuiViewport* viewport = ImGui::GetMainViewport();
        ImGui::SetNextWindowPos(ImVec2(viewport->WorkPos.x + 8.0f, viewport->WorkPos.y + 8.0f));
        ImGui::SetNextWindowSize(ImVec2(std::max(120.0f, viewport->WorkSize.x - 16.0f),
            std::max(80.0f, viewport->WorkSize.y - 48.0f)));
        ImGui::SetNextWindowDockID(0);
    } else if (layout.restorePending) {
        ImGui::SetNextWindowPos(layout.position);
        ImGui::SetNextWindowSize(layout.size);
        ImGui::SetNextWindowDockID(layout.dockId);
        layout.restorePending = false;
    }
    if (!ImGui::Begin(title, open)) return false;
    if (ImGui::SmallButton(storylandUiTextUtf8(layout.maximized ? L"Restore" : L"Maximize").c_str())) {
        if (layout.maximized) {
            layout.maximized = false;
            layout.restorePending = true;
        } else {
            layout.position = ImGui::GetWindowPos();
            layout.size = ImGui::GetWindowSize();
            layout.dockId = ImGui::GetWindowDockID();
            layout.maximized = true;
        }
    }
    ImGui::Separator();
    return true;
}

static int storylandPlatformIconIndex(StorylandSourcePlatform platform) {
    switch (platform) {
    case StorylandSourcePlatform::Pc: return 0;
    case StorylandSourcePlatform::Ps2: return 1;
    case StorylandSourcePlatform::Psp: return 2;
    case StorylandSourcePlatform::Mobile: return 3;
    default: return -1;
    }
}

static GLuint storylandPlatformOpenGlTexture(StorylandSourcePlatform platform) {
    const int index = storylandPlatformIconIndex(platform);
    if (index < 0) return 0;
    GLuint& texture = gSourcePlatformTextures[size_t(index)];
    if (texture != 0) return texture;

    static const int resources[] = {
        IDR_STORYLAND_PLATFORM_PC_PIXELS,
        IDR_STORYLAND_PLATFORM_PS2_PIXELS,
        IDR_STORYLAND_PLATFORM_PSP_PIXELS,
        IDR_STORYLAND_PLATFORM_MOBILE_PIXELS
    };
    HRSRC resource = FindResourceW(gInstance, MAKEINTRESOURCEW(resources[index]), RT_RCDATA);
    if (!resource || SizeofResource(gInstance, resource) != 16u * 16u * 4u) return 0;
    HGLOBAL loaded = LoadResource(gInstance, resource);
    const void* pixels = loaded ? LockResource(loaded) : nullptr;
    if (!pixels) return 0;

    GLint previousTexture = 0;
    glGetIntegerv(GL_TEXTURE_BINDING_2D, &previousTexture);
    glGenTextures(1, &texture);
    if (texture == 0) return 0;
    glBindTexture(GL_TEXTURE_2D, texture);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_CLAMP);
    glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_CLAMP);
    glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, 16, 16, 0,
                 GL_RGBA, GL_UNSIGNED_BYTE, pixels);
    glBindTexture(GL_TEXTURE_2D, GLuint(previousTexture));
    return texture;
}

static std::string storylandUiTextUtf8(const wchar_t* english) {
    return narrow(storylandUiText(english));
}

static std::string storylandUiWindowTitle(const wchar_t* english, const char* stableId) {
    return storylandUiTextUtf8(english) + "###" + stableId;
}

static std::string storylandPcControlKeyName(int key) {
    switch(key) {
    case VK_LBUTTON:return "Left mouse";
    case VK_RBUTTON:return "Right mouse";
    case VK_MBUTTON:return "Middle mouse";
    case VK_SHIFT:return "Shift";
    case VK_CONTROL:return "Ctrl";
    case VK_MENU:case VK_LMENU:return "Alt";
    case VK_SPACE:return "Space";
    case VK_RETURN:return "Enter";
    case VK_BACK:return "Backspace";
    case VK_UP:return "Up";
    case VK_DOWN:return "Down";
    case VK_LEFT:return "Left";
    case VK_RIGHT:return "Right";
    case VK_PRIOR:return "Page Up";
    case VK_NEXT:return "Page Down";
    default:break;
    }
    if((key>='A'&&key<='Z')||(key>='0'&&key<='9'))return std::string(1,char(key));
    char label[64]{};
    const auto scan=MapVirtualKeyW(UINT(key),MAPVK_VK_TO_VSC);
    if(scan&&GetKeyNameTextA(LONG(scan<<16),label,int(sizeof(label)))>0)return label;
    return "Key "+std::to_string(key);
}

static void storylandSaveControlBindings() {
    std::string error;
    if(!gStorylandController.saveBindings(storylandControlsDirectory(),error)) {
        gPlayTestStatus=error;
        setStatus(widen(error));
    }
}

static void drawStorylandControlRemap() {
    if(!gStorylandRemapOpen)return;
    struct PcBinding { int key; const char* action; };
    static constexpr PcBinding pcBindings[]={
        {'W',"Move forward / accelerate"},{'S',"Move backward / brake"},
        {'A',"Move / steer left"},{'D',"Move / steer right"},
        {'I',"Camera up"},{'K',"Camera down"},{'J',"Camera left"},{'L',"Camera right"},
        {'F',"Enter / exit vehicle"},{'G',"Attack / fire"},{'E',"Aim / lock on"},
        {'R',"Reload / radio / refocus"},{'V',"Camera view"},
        {VK_SHIFT,"Sprint"},{VK_LMENU,"Walk"},{VK_SPACE,"Jump / handbrake / dive up"},
        {VK_NUMPAD9,"Motorcycle lean forward"},{VK_NUMPAD6,"Motorcycle lean backward"},
        {VK_CONTROL,"Grab / rear takedown / dive down"},{'C',"Crouch"},{'X',"Release grab / cancel aim"},
        {'N',"Equalizer scope toggle (while aiming)"},
        {'Q',"Next weapon / look left in vehicle"},{'Z',"Left trigger"},
        {'H',"Look behind / left stick"},{'T',"PCSX2 camera / reload"},
        {'B',"Centre camera / look behind in vehicle"},{VK_UP,"Bike lean forward / drive forward / D-pad up"},
        {VK_DOWN,"Bike lean backward / drive backward / D-pad down"},{VK_LEFT,"Drive left / D-pad left"},
        {VK_RIGHT,"Drive right / D-pad right"},{VK_PRIOR,"Camera zoom in"},
        {VK_NEXT,"Camera zoom out"},{VK_LBUTTON,"Mouse fire"},{VK_RBUTTON,"Mouse aim"},
        {VK_MBUTTON,"Mouse action"},{VK_RETURN,"PCSX2 start"},{VK_BACK,"PCSX2 select"},
        {'1',"PCSX2 left trigger"},{'2',"PCSX2 left stick"},
        {'3',"PCSX2 right trigger"},{'4',"PCSX2 right stick"}
    };
    static constexpr const char* controllerActions[]={
        "Left shoulder / radio","Left trigger","Right shoulder / aim","Right trigger",
        "D-pad up","D-pad down","D-pad left","D-pad right",
        "Start / pause","Select / camera","Square / jump / brake","Triangle / enter / exit",
        "Cross / sprint / accelerate","Circle / attack","Left stick button","Right stick button"
    };
    static bool captureController=false;
    static bool captureAxis=false;
    static int captureIndex=-1;
    static bool waitForNextFrame=false;
    static std::array<bool,256> previousKeys{};
    std::array<bool,256> keys{};
    for(int key=1;key<256;++key)keys[size_t(key)]=(GetAsyncKeyState(key)&0x8000)!=0;
    if(captureIndex>=0) {
        if(waitForNextFrame)waitForNextFrame=false;
        else if(captureController) {
            const int source=captureAxis?gStorylandController.movedPhysicalAxis():
                gStorylandController.pressedPhysicalInput();
            if(source>=0) {
                if(captureAxis)gStorylandController.bindControllerAxis(size_t(captureIndex),source);
                else gStorylandController.bindControllerButton(size_t(captureIndex),source);
                captureIndex=-1;
            }
        } else {
            for(int key=1;key<256;++key) {
                if(key==VK_ESCAPE&&keys[size_t(key)]&&!previousKeys[size_t(key)]) {
                    captureIndex=-1;
                    break;
                }
                if(keys[size_t(key)]&&!previousKeys[size_t(key)]&&
                    key!=VK_LWIN&&key!=VK_RWIN) {
                    gStorylandController.bindPcKey(captureIndex,key);
                    captureIndex=-1;
                    break;
                }
            }
        }
        if(captureIndex<0)storylandSaveControlBindings();
    }
    previousKeys=keys;

    ImGui::SetNextWindowSize(ImVec2(580,560),ImGuiCond_FirstUseEver);
    if(ImGui::Begin("Remap Controls###StorylandControlRemap",&gStorylandRemapOpen)) {
        if(ImGui::BeginTabBar("Input devices")) {
            if(ImGui::BeginTabItem("PC keyboard and mouse")) {
                ImGui::TextWrapped("Select a binding, then press a key or mouse button. Escape cancels capture. A conflicting binding swaps places.");
                if(ImGui::Button("Restore PC defaults")) {
                    gStorylandController.resetPcBindings();captureIndex=-1;
                    storylandSaveControlBindings();
                }
                ImGui::BeginChild("PC bindings",ImVec2(0,0),true);
                for(const auto& binding:pcBindings) {
                    ImGui::PushID(binding.key);
                    ImGui::TextUnformatted(binding.action);
                    ImGui::SameLine(335);
                    const int key=gStorylandController.pcKey(binding.key);
                    const std::string label=captureIndex==binding.key&&!captureController?"Press key...":
                        storylandPcControlKeyName(key);
                    if(ImGui::Button(label.c_str(),ImVec2(140,0))) {
                        captureController=false;captureAxis=false;captureIndex=binding.key;waitForNextFrame=true;
                    }
                    ImGui::PopID();
                }
                ImGui::EndChild();
                ImGui::EndTabItem();
            }
            if(ImGui::BeginTabItem("Controller")) {
                ImGui::TextWrapped("%s. Select an action and press a controller button or trigger. To change a stick axis, move the new axis past its centre.",gStorylandController.status.c_str());
                if(ImGui::Button("Restore controller defaults")) {
                    gStorylandController.resetControllerBindings();captureIndex=-1;
                    storylandSaveControlBindings();
                }
                ImGui::BeginChild("Controller bindings",ImVec2(0,0),true);
                static constexpr const char* axes[]={"Movement horizontal","Movement vertical",
                    "Camera horizontal","Camera vertical"};
                for(size_t index=0;index<gStorylandController.controllerAxes.size();++index) {
                    ImGui::PushID(int(index)+100);
                    ImGui::TextUnformatted(axes[index]);
                    ImGui::SameLine(335);
                    const std::string label=captureController&&captureAxis&&captureIndex==int(index)?
                        "Move stick...":StorylandController::physicalAxisName(gStorylandController.controllerAxes[index]);
                    if(ImGui::Button(label.c_str(),ImVec2(140,0))) {
                        captureController=true;captureAxis=true;captureIndex=int(index);waitForNextFrame=true;
                    }
                    ImGui::SameLine();
                    if(ImGui::Checkbox("Invert",&gStorylandController.invertedAxes[index])) {
                        storylandSaveControlBindings();
                    }
                    ImGui::PopID();
                }
                ImGui::Separator();
                for(size_t index=0;index<gStorylandController.controllerButtons.size();++index) {
                    ImGui::PushID(int(index));
                    ImGui::TextUnformatted(controllerActions[index]);
                    ImGui::SameLine(335);
                    const std::string label=captureController&&!captureAxis&&captureIndex==int(index)?"Press button...":
                        StorylandController::physicalButtonName(gStorylandController.controllerButtons[index]);
                    if(ImGui::Button(label.c_str(),ImVec2(140,0))) {
                        captureController=true;captureAxis=false;captureIndex=int(index);waitForNextFrame=true;
                    }
                    ImGui::PopID();
                }
                ImGui::EndChild();
                ImGui::EndTabItem();
            }
            ImGui::EndTabBar();
        }
    }
    ImGui::End();
    if(!gStorylandRemapOpen)captureIndex=-1;
}

static void drawStorylandAudioOutputPanel() {
    if(!gStorylandAudioPanelOpen) {
        gStorylandAudioPanelTest.reset();
        gStorylandAudioPanelMixer.reset();
        return;
    }
    if(gPlayTestActive&&gPlayTestGameMode&&!gPlayTestDebugMenuOpen)return;
    ImGui::SetNextWindowSize(ImVec2(780,560),ImGuiCond_FirstUseEver);
    if(ImGui::Begin("Audio Output###StorylandAudioOutput",&gStorylandAudioPanelOpen)) {
        ImGui::TextWrapped("Build: %s",gStorylandAudioRevision);
        int audioMode=int(StorylandAudioMixer::currentAudioMode());
        if(ImGui::Combo("Audio Mode",&audioMode,"PC (Enhanced)\0PS2\0PSP\0"))
            storylandSelectAudioMode(storylandAudioModeFromInt(audioMode));
        ImGui::TextWrapped("PC (Enhanced): extra clarity. PS2: original sound. "
            "PSP: softer treble and narrower stereo.");
        const auto selected=StorylandAudioMixer::preferredOutputDevice();
        if(ImGui::BeginCombo("Output device",selected.empty()?"Windows default":selected.c_str())) {
            if(ImGui::Selectable("Windows default",selected.empty()))selectStorylandAudioOutput({});
            for(const auto& device:StorylandAudioMixer::outputDevices())
                if(ImGui::Selectable(device.c_str(),device==selected))selectStorylandAudioOutput(device);
            ImGui::EndCombo();
        }
        if(gStorylandAudioPanelMixer)ImGui::TextWrapped("%s",gStorylandAudioPanelMixer->statusText().c_str());
        else ImGui::TextUnformatted("Shared audio output is unavailable. See the test sound and Windows report.");
        if(ImGui::Button("Repair Storyland Audio"))refreshStorylandAudioSessionReport(true);
        ImGui::SameLine();
        if(ImGui::Button("Play Test Sound"))playStorylandAudioOutputTest();
        if(ImGui::Button("Refresh Report"))refreshStorylandAudioSessionReport(false);
        ImGui::SameLine();
        if(ImGui::Button("Copy Report")) {
            refreshStorylandAudioSessionReport(false);
            ImGui::SetClipboardText(storylandAudioOutputReport().c_str());
        }
        if(gStorylandAudioPanelTest)
            ImGui::Text("Test sound: %s | %u ms | %s",gStorylandAudioPanelTest->isPlaying()?"playing":"finished",
                gStorylandAudioPanelTest->playbackMilliseconds(),
                storylandWindowsAudio::utf8(gStorylandAudioPanelTest->outputBackend()).c_str());
        if(!gStorylandAudioPanelStatus.empty())ImGui::TextWrapped("%s",gStorylandAudioPanelStatus.c_str());
        ImGui::Separator();
        ImGui::BeginChild("Audio session report",ImVec2(0,0),ImGuiChildFlags_Borders,
            ImGuiWindowFlags_HorizontalScrollbar);
        ImGui::TextUnformatted(gStorylandAudioBuildReport.c_str());
        ImGui::Separator();
        ImGui::TextUnformatted(gStorylandAudioSessionReport.c_str());
        ImGui::EndChild();
    }
    ImGui::End();
    if(!gStorylandAudioPanelOpen) {
        gStorylandAudioPanelTest.reset();
        gStorylandAudioPanelMixer.reset();
    }
}

static void drawStorylandDearImGuiWorkspace() {
    if (!storylandDearImGuiFullWorkspace()) return;
    ImGuiIO& io = ImGui::GetIO();
    const float width = io.DisplaySize.x;
    const float height = io.DisplaySize.y;
    if (ImGui::BeginMainMenuBar()) {
        if (ImGui::BeginMenu(storylandUiTextUtf8(L"File").c_str())) { drawStorylandDearImGuiMenuItems(gFileMenu); ImGui::EndMenu(); }
        if (ImGui::BeginMenu("Modding")) {
            if (ImGui::MenuItem("MAIN.SCM Workbench"))
                PostMessageW(gMainWindow,WM_COMMAND,ID_MODDING_SCM,0);
            if (ImGui::MenuItem("DYOM Mission Designer"))
                PostMessageW(gMainWindow,WM_COMMAND,ID_MODDING_DYOM,0);
            if (ImGui::MenuItem("Sanny Builder workspace..."))
                PostMessageW(gMainWindow,WM_COMMAND,ID_MODDING_SANNY,0);
            ImGui::EndMenu();
        }
        if (ImGui::BeginMenu(storylandUiTextUtf8(L"Options").c_str())) {
            if(ImGui::BeginMenu("Audio")) {
                for(int index=0;index<3;++index) {
                    const auto mode=storylandAudioModeFromInt(index);
                    if(ImGui::MenuItem(storylandAudioModeName(mode),nullptr,
                        StorylandAudioMixer::currentAudioMode()==mode))
                        storylandSelectAudioMode(mode);
                }
                ImGui::Separator();
                if((!gPlayTestActive||!gPlayTestGameMode||gPlayTestDebugMenuOpen)&&
                    ImGui::MenuItem("Audio Output...",nullptr,&gStorylandAudioPanelOpen)&&gStorylandAudioPanelOpen)
                    openStorylandAudioOutputPanel();
                ImGui::EndMenu();
            }
            if(ImGui::BeginMenu("Controller")) {
                const auto choose=[&](const char* label,StorylandControllerMode mode) {
                    if(ImGui::MenuItem(label,nullptr,gStorylandController.mode==mode))gStorylandController.select(mode);
                };
                choose("Current controls",StorylandControllerMode::Current);
                choose("LCS/VCS PCSX2 controls",StorylandControllerMode::Pcsx2);
                choose("Xbox / PS5 / Bluetooth controller",StorylandControllerMode::Gamepad);
                ImGui::Separator();
                if(ImGui::MenuItem("Remap Controls..."))gStorylandRemapOpen=true;
                ImGui::Separator();
                if(gStorylandController.mode==StorylandControllerMode::Pcsx2)
                    ImGui::TextWrapped("WASD: move/steer | TFGH: camera | I: enter/exit | J: jump/brake | K: sprint/accelerate | L: attack | Q: centre camera/radio | E: aim/handbrake | 1/3: L2/R2 | 2/4: stick buttons | Enter: pause | Backspace: camera view");
                if(gStorylandController.mode==StorylandControllerMode::Gamepad) {
                    ImGui::TextWrapped("%s",gStorylandController.status.c_str());
                    ImGui::TextWrapped("Left stick: move/steer | Right stick: camera | A/Cross: sprint/accelerate | X/Square: jump/brake | Y/Triangle: enter/exit | B/Circle: attack | RB/R1: aim/handbrake | LB/L1: radio | Start/Options: pause");
                    if(ImGui::MenuItem("Connect Bluetooth device..."))
                        ShellExecuteW(gMainWindow,L"open",L"ms-settings:bluetooth",nullptr,nullptr,SW_SHOWNORMAL);
                }
                ImGui::EndMenu();
            }
            if (ImGui::BeginMenu(storylandUiTextUtf8(L"Play Options").c_str())) {
                drawStorylandPlayOptions(true);
                ImGui::EndMenu();
            }
            if (ImGui::BeginMenu(storylandUiTextUtf8(L"Language").c_str())) {
                drawStorylandDearImGuiMenuItems(gLanguageMenu);
                ImGui::EndMenu();
            }
            ImGui::EndMenu();
        }
        if (ImGui::BeginMenu(storylandUiTextUtf8(L"View").c_str())) {
            if (ImGui::MenuItem("Gallery", nullptr, false, gPlayTestActive)) storylandOpenGallery();
            if (gMode == StorylandMode::ArchiveFile || gMode == StorylandMode::DtzArchive) {
                ImGui::MenuItem(storylandUiTextUtf8(L"LCS/VCS player camera").c_str(), nullptr, &gPlayerCameraEnabled, !gPlayTestActive);
                if (ImGui::MenuItem(storylandUiTextUtf8(L"Refocus behind player").c_str(), "R", false, gPlayerCameraEnabled))
                    PostMessageW(gMainWindow, WM_COMMAND, ID_VIEW_REFOCUS_PLAYER_CAMERA, 0);
                if (ImGui::MenuItem(storylandUiTextUtf8(L"Collision surfaces (native COL2)").c_str(), nullptr, &gCollisionWireframeEnabled) && gCollisionWireframeEnabled) {
                    std::string error; if (!loadWorldGameContext(error)) setStatus(widen(error));
                    gDtzEmbeddedPreviewKind = DtzEmbeddedPreviewKind::None;
                }
                if (ImGui::MenuItem(storylandUiTextUtf8(L"Native paths").c_str(), nullptr, &gNativePathsVisible) && gNativePathsVisible) {
                    std::string error; if (!loadWorldGameContext(error)) setStatus(widen(error));
                    gDtzEmbeddedPreviewKind = DtzEmbeddedPreviewKind::None;
                }
                if (ImGui::MenuItem(storylandUiTextUtf8(gPlayTestActive ? L"Stop Play Test" : L"Play Test").c_str())) {
                    PostMessageW(gMainWindow, WM_COMMAND, ID_VIEW_PLAY_TEST, 0);
                }
                ImGui::Separator();
            }
            if (gMode == StorylandMode::CtwPakFile) {
                if (ImGui::BeginMenu("Sky")) {
                    ImGui::SliderFloat("Hour", &gCtwHour, 0.0f, 23.99f, "%.2f");
                    ImGui::Checkbox("Advance time", &gCtwAnimateTime);
                    ImGui::SliderFloat("Minutes per second", &gCtwMinutesPerSecond, 0.1f, 10.0f, "%.1f");
                    ImGui::EndMenu();
                }
                if (ImGui::BeginMenu("Weather")) {
                    if (gCtwRenderTimecycle.ready()) {
                        ImGui::Checkbox("Use PSP timecycle", &gCtwUseNativeTimecycle);
                        if (gCtwUseNativeTimecycle) ImGui::SliderInt("Native profile", &gCtwRenderProfile, 0, 7);
                    } else if (!gCtwRenderTimecycleError.empty()) {
                        ImGui::TextWrapped("%s", gCtwRenderTimecycleError.c_str());
                    }
                    ImGui::BeginDisabled(gCtwRenderTimecycle.ready() && gCtwUseNativeTimecycle);
                    ImGui::Checkbox("Change instantly", &gCtwImmediateWeather);
                    ImGui::Separator();
                    const char* names[] = {"Sunny", "Overcast", "Rain", "Fog", "Thunderstorm"};
                    for (int weather = 0; weather < 5; ++weather)
                        if (ImGui::MenuItem(names[weather], nullptr, gCtwWeather == weather)) gCtwWeather = weather;
                    ImGui::EndDisabled();
                    ImGui::EndMenu();
                }
                if (ImGui::BeginMenu("Shader")) {
                    if(ImGui::MenuItem("San Andreas",nullptr,gSanAndreasEnabled))
                        PostMessageW(gMainWindow,WM_COMMAND,49998,0);
                    ImGui::Separator();
                    const char* names[]={"LCS PS2","LCS PSP","VCS PS2","VCS PSP","CTW PSP","Mobile","Neo (SkyGFX)","Mafia 2","Cel","Budokai 1","PC"};
                    const int ids[]={49986,49987,49992,49993,49988,49991,49989,49999,50189,50190,int(StorylandPcShaderCommand)};
                    for(int i=0;i<11;++i){
                        const bool selected=i<4?gStoriesConsoleProfile==i&&!gStorylandPcShaderEnabled:
                            i==4?gCtwStoriesEnabled:i==5?gMobileEnabled:
                            i==6?gNeoEnabled:i==7?gMafia2Enabled:
                            i==8?gCelEnabled:i==9?gBudokaiEnabled:gStorylandPcShaderEnabled;
                        if(ImGui::MenuItem(names[i],nullptr,selected))
                            PostMessageW(gMainWindow,WM_COMMAND,ids[i],0);
                    }
                    const bool aeroMenuOpen=ImGui::BeginMenu("Aero");
                    if(ImGui::IsItemClicked(ImGuiMouseButton_Left))
                        PostMessageW(gMainWindow,WM_COMMAND,49990,0);
                    if(aeroMenuOpen){
                        for(int quality=0;quality<4;++quality)
                            if(ImGui::MenuItem(storylandAeroQuality(quality).name,nullptr,
                                    gAeroEnabled&&!gMafia2Enabled&&gAeroQuality==quality))
                                PostMessageW(gMainWindow,WM_COMMAND,49994+quality,0);
                        ImGui::EndMenu();
                    }
                    ImGui::Separator();
                    if(gAeroEnabled&&!gMafia2Enabled) {
                        ImGui::SliderFloat("Aero ambient occlusion", &gAeroAoStrength, 0.0f, 1.0f, "%.2f");
                        ImGui::Separator();
                    }
                    ImGui::MenuItem("CTW lighting", nullptr, &gCtwLighting);
                    ImGui::MenuItem("Wet surfaces", nullptr, &gCtwWetSurfaces);
                    ImGui::SliderFloat("Specular strength", &gCtwSpecularStrength, 0.0f, 1.0f, "%.2f");
                    ImGui::SliderFloat("Roughness", &gCtwRoughness, 0.08f, 1.0f, "%.2f");
                    ImGui::EndMenu();
                }
                ImGui::Separator();
            }
            if (ImGui::BeginMenu("Panels")) {
                bool visible = !((gPlayTestActive||gStorylandFrontendBootPending) && gPlayTestPanelsHidden);
                if (ImGui::MenuItem("Show side panels", "Home", visible) && gPlayTestActive)
                    storylandSetPlayTestPanelsHidden(!gPlayTestPanelsHidden);
                const auto panelOption = [&](const char* label, bool& open) {
                    const bool shown = visible && open;
                    if (ImGui::MenuItem(label, nullptr, shown)) {
                        if (!visible) { storylandSetPlayTestPanelsHidden(false); visible = true; }
                        open = !shown;
                        gResetPanelLayout = true;
                    }
                };
                panelOption("Resources", gDearImGuiResourcesOpen);
                panelOption("Details", gDearImGuiInspectorOpen);
                panelOption("Actions", gDearImGuiActionsOpen);
                panelOption("Play Test", gDearImGuiPlayTestOpen);
                panelOption("Game data", gDtzEditorOpen);
                ImGui::EndMenu();
            }
            drawStorylandDearImGuiMenuItems(gViewMenu);
            ImGui::EndMenu();
        }
        if (ImGui::BeginMenu(storylandUiTextUtf8(L"Panels").c_str())) {
            if ((gPlayTestActive||gStorylandFrontendBootPending) && gPlayTestPanelsHidden) {
                if (ImGui::MenuItem("Show side panels", "Home")) storylandSetPlayTestPanelsHidden(false);
                ImGui::Separator();
            }
            if (ImGui::MenuItem(storylandUiTextUtf8(L"Resources").c_str(), nullptr, &gDearImGuiResourcesOpen)) gResetPanelLayout = true;
            if (ImGui::MenuItem(storylandUiTextUtf8(L"Details").c_str(), nullptr, &gDearImGuiInspectorOpen)) gResetPanelLayout = true;
            if (ImGui::MenuItem(storylandUiTextUtf8(L"Actions").c_str(), nullptr, &gDearImGuiActionsOpen)) gResetPanelLayout = true;
            if (ImGui::MenuItem(storylandUiTextUtf8(L"Play Test").c_str(), nullptr, &gDearImGuiPlayTestOpen)) gResetPanelLayout = true;
            ImGui::MenuItem("Game data", nullptr, &gDtzEditorOpen, gMode == StorylandMode::DtzArchive);
            ImGui::Separator();
            if (ImGui::MenuItem("Reset layout")) gResetPanelLayout = true;
            ImGui::EndMenu();
        }
        if (ImGui::BeginMenu(storylandUiTextUtf8(L"Help").c_str())) { drawStorylandDearImGuiMenuItems(gHelpMenu); ImGui::EndMenu(); }
        ImGui::Separator();
        ImGui::Dummy(ImVec2(ImGui::CalcTextSize("STORYLAND").x, ImGui::GetTextLineHeight()));
        if(gMode==StorylandMode::DtzArchive||
            (gMode==StorylandMode::ArchiveFile&&!gArchiveBrowser.placements().empty())||gPlayTestActive) {
            ImGui::SameLine();
            ImGui::BeginDisabled(gPlayTestLoading);
            const ImVec2 playPosition=ImGui::GetCursorScreenPos();
            if(ImGui::Button(storylandUiTextUtf8(L"   Play...").c_str()))ImGui::OpenPopup("StorylandPlayOptions");
            const ImVec2 playEnd=ImGui::GetItemRectMax();
            const float centerY=(playPosition.y+playEnd.y)*0.5f;
            ImGui::GetWindowDrawList()->AddTriangleFilled(
                ImVec2(playPosition.x+6,centerY-5),ImVec2(playPosition.x+6,centerY+5),
                ImVec2(playPosition.x+14,centerY),IM_COL32(55,220,85,255));
            ImGui::SetNextWindowPos(ImVec2(playPosition.x,playEnd.y));
            if(ImGui::BeginPopup("StorylandPlayOptions")) {
                if(ImGui::MenuItem("Test"))PostMessageW(gMainWindow,WM_COMMAND,ID_VIEW_PLAY_TEST,1);
                if(ImGui::MenuItem("Game"))PostMessageW(gMainWindow,WM_COMMAND,ID_VIEW_PLAY_TEST,2);
                ImGui::EndPopup();
            }
            ImGui::SameLine();
            ImGui::BeginDisabled(!gPlayTestActive&&!gStorylandFrontendBootPending);
            const ImVec2 stopPosition=ImGui::GetCursorScreenPos();
            if(ImGui::Button("   Stop"))PostMessageW(gMainWindow,WM_COMMAND,ID_VIEW_PLAY_TEST,3);
            const float stopY=(stopPosition.y+ImGui::GetItemRectMax().y)*0.5f;
            ImGui::GetWindowDrawList()->AddRectFilled(ImVec2(stopPosition.x+6,stopY-4),
                ImVec2(stopPosition.x+14,stopY+4),IM_COL32(235,65,65,255));
            ImGui::EndDisabled();
            ImGui::EndDisabled();
            if (!gPlayTestActive) {
                ImGui::SameLine();
                if (ImGui::Button("MAIN.SCM")) PostMessageW(gMainWindow,WM_COMMAND,ID_MODDING_SCM,0);
                ImGui::SameLine();
                if (ImGui::Button("DYOM")) PostMessageW(gMainWindow,WM_COMMAND,ID_MODDING_DYOM,0);
            }
        }
        if (gSourcePlatform != StorylandSourcePlatform::None) {
            const GLuint texture = storylandPlatformOpenGlTexture(gSourcePlatform);
            if (texture != 0) {
                const ImVec2 menuPosition = ImGui::GetWindowPos();
                const ImVec2 menuSize = ImGui::GetWindowSize();
                const float iconSize = 16.0f;
                const ImVec2 iconPosition(menuPosition.x + menuSize.x - iconSize - 10.0f,
                    menuPosition.y + (menuSize.y - iconSize) * 0.5f);
                const ImVec2 iconEnd(iconPosition.x + iconSize, iconPosition.y + iconSize);
                ImGui::GetWindowDrawList()->AddImage(static_cast<ImTextureID>(texture),
                    iconPosition, iconEnd);
                if (ImGui::IsMouseHoveringRect(iconPosition, iconEnd)) {
                    const char* platformLabel = gSourcePlatform == StorylandSourcePlatform::Pc
                        ? "PC format" : gSourcePlatform == StorylandSourcePlatform::Ps2
                        ? "PlayStation 2 format" : gSourcePlatform == StorylandSourcePlatform::Psp
                        ? "PlayStation Portable format" : "Mobile format";
                    ImGui::SetTooltip("%s", platformLabel);
                }
            }
        }
        ImGui::EndMainMenuBar();
    }
    drawStorylandControlRemap();
    if ((gPlayTestActive||gStorylandFrontendBootPending) && gPlayTestPanelsHidden) return;
    const bool ctwDocument = gMode == StorylandMode::CtwPakFile || gMode == StorylandMode::CtwWadFile;
    const bool previewDocument = ctwDocument || gMode == StorylandMode::MediaFile ||
        gMode == StorylandMode::TextureArchive ||
        (gMode == StorylandMode::DtzArchive && gDtzEmbeddedPreviewKind == DtzEmbeddedPreviewKind::TextureArchive);
    const float top = ImGui::GetFrameHeight() + 8.0f;
    const float bottom = 32.0f;
    const float left = previewDocument ? std::min(320.0f, width * 0.25f) : std::clamp(width * 0.26f, 260.0f, 410.0f);
    const float right = previewDocument ? std::min(300.0f, width * 0.24f) : std::clamp(width * 0.27f, 280.0f, 430.0f);
    const float availableHeight = std::max(120.0f, height - top - bottom - 10.0f);
    const ImGuiWindowFlags paneFlags = previewDocument ?
        ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoDocking : ImGuiWindowFlags_None;
    if (previewDocument) {
        const float previewX = gDearImGuiResourcesOpen ? left + 16.0f : 8.0f;
        const float previewRight = (gDearImGuiInspectorOpen || gDearImGuiActionsOpen) ? right + 16.0f : 8.0f;
        ImGui::SetNextWindowPos(ImVec2(previewX, top), ImGuiCond_Always);
        ImGui::SetNextWindowSize(ImVec2(std::max(1.0f, width - previewX - previewRight), availableHeight), ImGuiCond_Always);
        ImGui::SetNextWindowDockID(0);
        if (ImGui::Begin("Preview###DocumentPreview", nullptr, paneFlags)) {
            if (ctwDocument) {
                const bool pak = gMode == StorylandMode::CtwPakFile;
                ImGui::TextUnformatted(pak ? (gCtwPakFile.header().mobile ? "Chinatown Wars Mobile GAME.PAK" : "Chinatown Wars PSP GAME.PAK") : "Chinatown Wars ROM.WAD");
                if (ImGui::Button("Export all resources"))
                    PostMessageW(gMainWindow, WM_COMMAND, ID_CTW_EXPORT_ALL, 0);
                if (pak && !gCtwPakFile.header().mobile) {
                    ImGui::SameLine();
                    if (ImGui::Button("Liberty City"))
                        PostMessageW(gMainWindow, WM_COMMAND, ID_CTW_VIEW_CITY, 0);
                }
                ImGui::Separator();
                if (!gCtwPreviewError.empty()) ImGui::TextWrapped("%s", gCtwPreviewError.c_str());
                if (!gCtwPreviewRenderError.empty()) ImGui::TextWrapped("%s", gCtwPreviewRenderError.c_str());
                if (gCtwCityVisible) drawCtwCityPanel();
                else if (gCtwSelectedBytes.empty()) ImGui::TextWrapped("Select a resource to inspect its contents.");
                else {
                    const std::string extension = pak && gSelectedIndex >= 0 &&
                        size_t(gSelectedIndex) < gCtwPakFile.resources().size() ?
                        gCtwPakFile.resources()[size_t(gSelectedIndex)].type : storyland_ctw::guessResourceExtension(gCtwSelectedBytes);
                    ImGui::Text("Resource %d  |  %zu bytes  |  %s", gSelectedIndex, gCtwSelectedBytes.size(), extension.c_str());
                    if (ImGui::Button("Export resource")) PostMessageW(gMainWindow, WM_COMMAND, ID_FILE_EXPORT_SELECTED_RESOURCE, 0);
                    ImGui::SameLine();
                    ImGui::Checkbox("Data", &gCtwShowData);
                    if (extension == ".pspanimtex" && gCtwSelectedBytes.size() >= 20) {
                        const int count = storyland_ctw::read16(gCtwSelectedBytes.data() + 16);
                        if (count > 0 && ImGui::SliderInt("Texture frame", &gCtwTextureFrame, 0, count - 1)) decodeCtwSelectedVisual();
                    }
                    if (extension == ".world") {
                        if (ImGui::Combo("Sector quadrant", &gCtwWorldSection, "0\0" "1\0" "2\0" "3\0")) decodeCtwSelectedVisual();
                        ImGui::Text("%zu placed models", gCtwPlacementCount);
                    }
                    if (!gCtwPreviewModel.vertices.empty()) {

                        if (!gCtwShaderError.empty()) ImGui::TextWrapped("%s", gCtwShaderError.c_str());
                        if (ImGui::Button("Reset view")) { gCtwYaw = 35; gCtwPitch = 55; gCtwZoom = 1; }
                        ImGui::Text("%zu vertices  |  %zu materials", gCtwPreviewModel.vertices.size(), gCtwPreviewModel.parts.size());
                    }
                    if (!gCtwShowData && gDocumentPreviewTexture) {
                        ImVec2 size = ImGui::GetContentRegionAvail();
                        if (!gCtwPreviewImage.rgba.empty()) {
                            const float factor = std::min(size.x / gCtwPreviewImage.width, size.y / gCtwPreviewImage.height);
                            size = ImVec2(gCtwPreviewImage.width * factor, gCtwPreviewImage.height * factor);
                        }
                        ImGui::Image(static_cast<ImTextureID>(gDocumentPreviewTexture), size,
                            gCtwPreviewModel.vertices.empty() ? ImVec2(0, 0) : ImVec2(0, 1),
                            gCtwPreviewModel.vertices.empty() ? ImVec2(1, 1) : ImVec2(1, 0));
                        if (!gCtwPreviewModel.vertices.empty() && ImGui::IsItemHovered()) {
                            if (ImGui::IsMouseDragging(ImGuiMouseButton_Left)) {
                                gCtwYaw += io.MouseDelta.x * 0.5f;
                                gCtwPitch = std::clamp(gCtwPitch + io.MouseDelta.y * 0.5f, -89.0f, 89.0f);
                            }
                            gCtwZoom = std::clamp(gCtwZoom * std::pow(1.15f, io.MouseWheel), 0.05f, 30.0f);
                        }
                    } else if (!gCtwShowData && gMode == StorylandMode::CtwWadFile && gCtwNativeTimecycle.ready()) {
                        ImGui::TextUnformatted("PSP timecycle.dat: 8 weather profiles, 55 channels, 24 hours");
                        ImGui::SliderInt("Weather profile", &gCtwNativeWeather, 0, 7);
                        ImGui::SliderInt("Hour", &gCtwNativeHour, 0, 23);
                        ImGui::TextWrapped("Stored -1 values inherit between neighbouring hours. Colour values include the PSP colour curve. Channel purposes are still being identified.");
                        if (ImGui::BeginTable("NativeTimecycle", 4, ImGuiTableFlags_RowBg | ImGuiTableFlags_ScrollY,
                            ImVec2(0, ImGui::GetContentRegionAvail().y))) {
                            ImGui::TableSetupColumn("Channel"); ImGui::TableSetupColumn("Type");
                            ImGui::TableSetupColumn("Stored"); ImGui::TableSetupColumn("Resolved");
                            ImGui::TableSetupScrollFreeze(0, 1); ImGui::TableHeadersRow();
                            for (size_t channel = 0; channel < storyland_ctw::PspTimecycle::ChannelCount; ++channel) {
                                ImGui::TableNextRow(); ImGui::TableNextColumn(); ImGui::Text("%zu", channel);
                                ImGui::TableNextColumn(); ImGui::TextUnformatted(storyland_ctw::PspTimecycle::channelName(channel));
                                ImGui::TableNextColumn(); ImGui::Text("%.3f", gCtwNativeTimecycle.raw(gCtwNativeWeather, channel, gCtwNativeHour) / 4096.0f);
                                ImGui::TableNextColumn(); ImGui::Text("%u", unsigned(gCtwNativeTimecycle.value(gCtwNativeWeather, channel, gCtwNativeHour)));
                            }
                            ImGui::EndTable();
                        }
                    } else if (!gCtwShowData) {
                        ImGui::TextWrapped("This resource has no visual decoder yet. Use Data to inspect its bytes or export the original resource.");
                        if (ImGui::Button("Open resource")) PostMessageW(gMainWindow, WM_COMMAND, ID_FILE_OPEN_EMBEDDED, 0);
                    }
                    if (gCtwShowData) {
                    if (ImGui::BeginChild("Resource bytes", ImVec2(0, 0), ImGuiChildFlags_Borders,
                        ImGuiWindowFlags_HorizontalScrollbar)) {
                        constexpr size_t columns = 16;
                        ImGuiListClipper clipper;
                        clipper.Begin(int((gCtwSelectedBytes.size() + columns - 1) / columns));
                        while (clipper.Step()) {
                            for (int row = clipper.DisplayStart; row < clipper.DisplayEnd; ++row) {
                                const size_t offset = size_t(row) * columns;
                                std::ostringstream line;
                                line << std::hex << std::setfill('0') << std::setw(8) << offset << "  ";
                                std::string characters;
                                for (size_t column = 0; column < columns; ++column) {
                                    if (offset + column < gCtwSelectedBytes.size()) {
                                        const unsigned value = gCtwSelectedBytes[offset + column];
                                        line << std::setw(2) << value << ' ';
                                        characters.push_back(value >= 32 && value <= 126 ? char(value) : '.');
                                    } else line << "   ";
                                }
                                line << " " << characters;
                                ImGui::TextUnformatted(line.str().c_str());
                            }
                        }
                    }
                    ImGui::EndChild();
                    }
                }
            } else if (gDocumentPreviewTexture) {
                const ImVec2 size = ImGui::GetContentRegionAvail();
                ImGui::Image(static_cast<ImTextureID>(gDocumentPreviewTexture),
                    ImVec2(std::max(1.0f, size.x), std::max(1.0f, size.y)), ImVec2(0, 1), ImVec2(1, 0));
            }
        }
        ImGui::End();
    }

    if (gDearImGuiResourcesOpen) {
        ImGui::SetNextWindowPos(ImVec2(8.0f, top), (previewDocument || gResetPanelLayout) ? ImGuiCond_Always : ImGuiCond_FirstUseEver);
        ImGui::SetNextWindowSize(ImVec2(left, availableHeight), (previewDocument || gResetPanelLayout) ? ImGuiCond_Always : ImGuiCond_FirstUseEver);
        if (previewDocument) ImGui::SetNextWindowDockID(0);
        if (ImGui::Begin(storylandUiWindowTitle(L"Resources", "Resources").c_str(), &gDearImGuiResourcesOpen, paneFlags)) {
            ImGui::TextDisabled("Models  /  Textures  /  World");
            if (gMode == StorylandMode::DtzArchive && ImGui::Button("Edit game data...")) gDtzEditorOpen = true;
            ImGui::Separator();
            gDearImGuiTreeSelectionChanged = false;
            drawStorylandDearImGuiTree(TreeView_GetRoot(gTree));
        }
        ImGui::End();
    }

    if (gDearImGuiInspectorOpen) {
        const bool worldTools = (gMode == StorylandMode::DtzArchive || gMode == StorylandMode::ArchiveFile) && gDearImGuiPlayTestOpen;
        const float inspectorHeight = worldTools ? availableHeight * 0.38f : gDearImGuiActionsOpen ? availableHeight * 0.65f : availableHeight;
        if (beginStorylandPanel("Details", &gDearImGuiInspectorOpen,
            ImVec2(std::max(0.0f, width - right - 8.0f), top),
            ImVec2(right, inspectorHeight), gDetailsPanelLayout, previewDocument)) {
            if (ImGui::BeginTable("##details", 2, ImGuiTableFlags_RowBg |
                ImGuiTableFlags_SizingStretchProp | ImGuiTableFlags_BordersInnerH)) {
                ImGui::TableSetupColumn("Property", ImGuiTableColumnFlags_WidthStretch, 0.40f);
                ImGui::TableSetupColumn("Value", ImGuiTableColumnFlags_WidthStretch, 0.60f);
                ImGui::TableHeadersRow();
                for (const auto& entry : gDetailsRows) {
                    ImGui::TableNextRow();
                    ImGui::TableNextColumn();
                    ImGui::TextDisabled("%s", narrow(entry.first).c_str());
                    ImGui::TableNextColumn();
                    ImGui::TextWrapped("%s", narrow(entry.second).c_str());
                }
                ImGui::EndTable();
            }
        }
        ImGui::End();
    }

    if (gDearImGuiActionsOpen) {
        const bool worldTools = (gMode == StorylandMode::DtzArchive || gMode == StorylandMode::ArchiveFile) && gDearImGuiPlayTestOpen;
        const float actionsY = top + availableHeight * (worldTools ? 0.39f : 0.66f) + 5.0f;
        if (beginStorylandPanel("Actions", &gDearImGuiActionsOpen,
            ImVec2(std::max(0.0f, width - right - 8.0f), actionsY),
            ImVec2(right, worldTools ? 70.0f : std::max(80.0f, height - actionsY - bottom - 5.0f)), gActionsPanelLayout, previewDocument)) {
            if (gMode == StorylandMode::MediaFile &&
                gMediaFile.kind() == StorylandMediaKind::Video) {
                const uint64_t total = gMediaFile.videoFrameCountEstimate();
                const int maxFrame = int(std::min<uint64_t>(total > 0 ? total - 1 : 0,
                    uint64_t((std::numeric_limits<int>::max)() - 1)));
                int current = int(std::min<uint64_t>(gMediaFile.videoFrameIndex(), uint64_t(maxFrame)));
                if (maxFrame > 0 && ImGui::SliderInt("Frame", &current, 0, maxFrame)) {
                    std::string error;
                    if (gMediaFile.seekVideoFrame(uint64_t(current), error)) {
                        updateMediaVideoDetails();
                    } else if (!error.empty()) {
                        setStatus(L"Video seek failed: " + widen(error));
                    }
                }
                ImGui::Separator();
            }
            const HWND buttons[] = {gActionPrimary, gActionSecondary, gActionTertiary, gActionQuaternary};
            const UINT ids[] = {ID_ACTION_PRIMARY, ID_ACTION_SECONDARY, ID_ACTION_TERTIARY, ID_ACTION_QUATERNARY};
            for (int index = 0; index < 4; ++index) {
                if (!buttons[index] || !gDearImGuiActionAvailable[index]) continue;
                wchar_t caption[128]{};
                GetWindowTextW(buttons[index], caption, 128);
                ImGui::BeginDisabled(!gDearImGuiActionEnabled[index]);
                if (ImGui::Button(narrow(caption).c_str(), ImVec2(-1.0f, 0.0f)))
                    PostMessageW(gMainWindow, WM_COMMAND, ids[index], 0);
                ImGui::EndDisabled();
            }
            if (gMode == StorylandMode::ModelFile && !gModelFile.isEmptyDraft()) {
                if (ImGui::Button("Export OBJ...", ImVec2(-1.0f, 0.0f)))
                    exportCurrentModelObj();
            }
            if (gArchiveCreateDirInlineButton && IsWindowVisible(gArchiveCreateDirInlineButton) &&
                ImGui::Button("No .DIR, create one?", ImVec2(-1.0f, 0.0f)))
                PostMessageW(gMainWindow, WM_COMMAND, ID_ARCHIVE_CREATE_DIR_INLINE, 0);
        }
        ImGui::End();
    }

    if (gModelExportPopupRequested) {
        ImGui::OpenPopup("Export Model");
        gModelExportPopupRequested = false;
    }
    if (ImGui::BeginPopupModal("Export Model", nullptr, ImGuiWindowFlags_AlwaysAutoResize)) {
        const bool sourceDff = storylandSourceModelIsDff();
        ImGui::TextUnformatted(sourceDff ? "Export MDL" : "Export DFF");
        ImGui::TextDisabled("Choose the game and platform:");
        ImGui::Separator();
        if (sourceDff) {
            const StorylandModelConversion::Target targets[] = {
                StorylandModelConversion::Target::LcsPs2Mdl,
                StorylandModelConversion::Target::LcsPspMdl,
                StorylandModelConversion::Target::VcsPs2Mdl,
                StorylandModelConversion::Target::VcsPspMdl
            };
            const char* labels[] = {"LCS PS2", "LCS PSP", "VCS PS2", "VCS PSP"};
            for (int index = 0; index < 4; ++index) {
                if (ImGui::Button(labels[index], ImVec2(260.0f, 0.0f))) {
                    exportCurrentModelConverted(targets[index]);
                    ImGui::CloseCurrentPopup();
                }
            }
        } else {
            if (ImGui::Button("San Andreas", ImVec2(260.0f, 0.0f))) {
                exportCurrentModelConverted(StorylandModelConversion::Target::SanAndreasDff);
                ImGui::CloseCurrentPopup();
            }
            if (ImGui::Button("Mobile (LCS)", ImVec2(260.0f, 0.0f))) {
                exportCurrentModelConverted(StorylandModelConversion::Target::MobileLcsDff);
                ImGui::CloseCurrentPopup();
            }
        }
        ImGui::Separator();
        if (ImGui::Button("Wavefront OBJ", ImVec2(260.0f, 0.0f))) {
            exportCurrentModelObj();
            ImGui::CloseCurrentPopup();
        }
        if (ImGui::Button("Cancel", ImVec2(260.0f, 0.0f)))ImGui::CloseCurrentPopup();
        ImGui::EndPopup();
    }

    ImGui::SetNextWindowPos(ImVec2(0.0f, std::max(0.0f, height - 28.0f)), ImGuiCond_Always);
    ImGui::SetNextWindowSize(ImVec2(width, 28.0f), ImGuiCond_Always);
    if (ImGui::Begin("##Status", nullptr, ImGuiWindowFlags_NoTitleBar |
        ImGuiWindowFlags_NoScrollbar | ImGuiWindowFlags_NoMove |
        ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoDocking)) {
        ImGui::TextUnformatted(narrow(gStatusText).c_str());
    }
    ImGui::End();
}

