static void drawStorylandAnalysisWorkspace() {
    const ImVec2 display = ImGui::GetIO().DisplaySize;
    ImGui::SetNextWindowPos(ImVec2(0,0), ImGuiCond_Always);
    ImGui::SetNextWindowSize(display, ImGuiCond_Always);
    if (ImGui::Begin(storylandUiWindowTitle(L"Analyze", "Analyze").c_str(), nullptr, ImGuiWindowFlags_NoDecoration |
        ImGuiWindowFlags_NoMove | ImGuiWindowFlags_NoResize | ImGuiWindowFlags_NoDocking)) {
        if (ImGui::Button("Back to resource")) PostMessageW(gMainWindow, WM_COMMAND, ID_RESOURCE_ANALYZE_BACK, 0);
        ImGui::SameLine(); ImGui::TextUnformatted(narrow(gAnalysisGraphName).c_str());
        ImGui::Separator();
        const auto& nodes = gAnalysisGraph.nodes();
        int selected = gSelectedKind == StorylandTreeKind::AnalyzeGraphNode ? gSelectedIndex : 0;
        if (ImGui::BeginTable("##graphLayout", 2, ImGuiTableFlags_Resizable | ImGuiTableFlags_BordersInnerV)) {
            ImGui::TableSetupColumn("Graph", ImGuiTableColumnFlags_WidthStretch);
            ImGui::TableSetupColumn("Node", ImGuiTableColumnFlags_WidthFixed, 300);
            ImGui::TableNextRow(); ImGui::TableNextColumn();
            const int clicked = gAnalysisCanvas.draw(gAnalysisGraph, selected);
            if (clicked >= 0) { selected = clicked; selectAnalyzeGraphNode(clicked); }
            ImGui::TableNextColumn();
            ImGui::BeginChild("##nodeDetails", ImVec2(0,0));
            if (selected >= 0 && size_t(selected) < nodes.size()) {
                const auto& node = nodes[size_t(selected)];
                ImGui::TextWrapped("%s", node.label.c_str());
                if (ImGui::BeginTable("##nodeFields",2,ImGuiTableFlags_RowBg)) {
                    ImGui::TableNextRow(); ImGui::TableNextColumn(); ImGui::TextDisabled("Offset");
                    ImGui::TableNextColumn(); ImGui::Text("0x%llX", (unsigned long long)node.offset);
                    ImGui::TableNextRow(); ImGui::TableNextColumn(); ImGui::TextDisabled("Bytes");
                    ImGui::TableNextColumn(); ImGui::Text("%llu", (unsigned long long)node.size);
                    ImGui::TableNextRow(); ImGui::TableNextColumn(); ImGui::TextDisabled("Type");
                    ImGui::TableNextColumn(); ImGui::Text("0x%X", node.type);
                    ImGui::TableNextRow(); ImGui::TableNextColumn(); ImGui::TextDisabled("Version");
                    ImGui::TableNextColumn(); ImGui::Text("0x%X", node.version);
                    ImGui::EndTable();
                }
                ImGui::TextWrapped("%s",node.description.c_str());
                if (node.offset < gAnalysisGraphBytes.size()) {
                    const uint64_t count = std::min<uint64_t>(256,std::min<uint64_t>(node.size,gAnalysisGraphBytes.size()-node.offset));
                    ImGui::SeparatorText("Bytes");
                    for (uint64_t row=0; row<count; row+=8) {
                        std::ostringstream line;
                        line << std::hex << std::uppercase << std::setfill('0') << std::setw(8) << (node.offset+row) << "  ";
                        for (uint64_t column=0;column<8&&row+column<count;++column)
                            line << std::setw(2) << unsigned(gAnalysisGraphBytes[size_t(node.offset+row+column)]) << ' ';
                        ImGui::TextUnformatted(line.str().c_str());
                    }
                }
            }
            ImGui::SeparatorText("Nodes");
            static ImGuiTextFilter filter;
            filter.Draw("Find node");
            for (size_t index=0;index<nodes.size();++index) {
                if (!filter.PassFilter(nodes[index].label.c_str())) continue;
                ImGui::PushID(int(index));
                if (ImGui::Selectable(nodes[index].label.c_str(),selected==int(index))) selectAnalyzeGraphNode(int(index));
                ImGui::PopID();
            }
            ImGui::EndChild(); ImGui::EndTable();
        }
    }
    ImGui::End();
}

