static std::filesystem::path storylandModdingScmPath() {
    if(gMode==StorylandMode::ScmFile) return gScmFile.sourcePath();
    if(gPlayTestActive && !gPlayTestScmPath.empty()) return gPlayTestScmPath;
    if(gDtzArchive.sourcePath().empty()) return {};
    std::wstring path;
    std::string error;
    if(storylandFindRequiredPlayTestScm(gDtzArchive.sourcePath(),gArchiveBrowser.lvzPath(),
        gDtzArchive.gameVariant()==StorylandDtzGameVariant::Vcs,path,error,gDtzArchive.modloader())) return path;
    return {};
}

static std::filesystem::path chooseStorylandModdingFile(StorylandModdingFileKind kind,bool save) {
    std::array<wchar_t,32768> filename{};
    const wchar_t* filter=L"Stories SCM (*.scm)\0*.scm\0All files (*.*)\0*.*\0";
    const wchar_t* extension=L"scm";
    if(kind==StorylandModdingFileKind::Dyom) {
        filter=L"DYOM mission (*.dyom;*.dyomvcs)\0*.dyom;*.dyomvcs\0All files (*.*)\0*.*\0";
        extension=L"dyom";
    } else if(kind==StorylandModdingFileKind::ScmPatch) {
        filter=L"Storyland SCM patch (*.scmpatch)\0*.scmpatch\0All files (*.*)\0*.*\0";
        extension=L"scmpatch";
    } else if(kind==StorylandModdingFileKind::Disassembly) {
        filter=L"Readable disassembly (*.txt)\0*.txt\0All files (*.*)\0*.*\0";
        extension=L"txt";
    }
    OPENFILENAMEW dialog{};
    dialog.lStructSize=sizeof(dialog);
    dialog.hwndOwner=gMainWindow;
    dialog.lpstrFilter=filter;
    dialog.lpstrFile=filename.data();
    dialog.nMaxFile=DWORD(filename.size());
    dialog.lpstrDefExt=extension;
    dialog.Flags=OFN_EXPLORER|OFN_NOCHANGEDIR|OFN_PATHMUSTEXIST|
        (save?OFN_OVERWRITEPROMPT:OFN_FILEMUSTEXIST);
    const bool selected=save?GetSaveFileNameW(&dialog)!=FALSE:GetOpenFileNameW(&dialog)!=FALSE;
    return selected?std::filesystem::path(filename.data()):std::filesystem::path{};
}

static bool canStartStorylandDyom(std::string& error) {
    error.clear();
    if(gDtzArchive.unpackedBytes().empty() || gDtzArchive.gameVariant()!=StorylandDtzGameVariant::Vcs)
        error="Open Vice City Stories game data to play a DYOM mission.";
    else if(gPlayTestLoading) error="Play Test is still initializing.";
    else if(gPlayTestActive && gPlayTestGameMode) error="Stop Play Game before testing an authored mission.";
    else if(gMultiplayer.connected()) error="Disconnect co-op before testing an authored mission.";
    return error.empty();
}

static bool startStorylandDyom(const StorylandDyomProject& project,std::string& error) {
    if(!canStartStorylandDyom(error)) return false;
    StorylandDyomCompiled compiled;
    if(!storylandCompileDyomVcs(project,compiled,error)) return false;
    for(const auto& requirement:compiled.requiredModels) {
        if(!storylandNativeModelAvailable(gDtzArchive,requirement.model)) {
            error="Entity "+requirement.entityId+" uses unavailable native model "+
                std::to_string(requirement.model)+".";
            return false;
        }
        const bool actor=storylandDecodePedStats(gDtzArchive.unpackedBytes(),uint32_t(requirement.model),true).valid;
        const bool vehicle=storylandVehicleDomain(gDtzArchive.unpackedBytes(),uint32_t(requirement.model),true)!=StorylandVehicleDomain::Unknown;
        if((requirement.kind==StorylandDyomEntityKind::Actor&&!actor) ||
            (requirement.kind==StorylandDyomEntityKind::Vehicle&&!vehicle) ||
            ((requirement.kind==StorylandDyomEntityKind::Object || requirement.kind==StorylandDyomEntityKind::Pickup) && (actor||vehicle))) {
            error="Entity "+requirement.entityId+" has a model of the wrong type for "+
                storylandDyomEntityKindName(requirement.kind)+".";
            return false;
        }
    }
    if(!compiled.requiredWeapons.empty()) {
        std::vector<StorylandWeaponDefinition> definitions;
        std::vector<StorylandPlayTestAsset> assets;
        std::string diagnostic;
        if(!gPlayTestActive) storylandLoadPlayTestWeapons(gDtzArchive,definitions,assets,diagnostic);
        const auto& available=gPlayTestActive?gPlayTestRuntime.weapons:definitions;
        for(int32_t weapon:compiled.requiredWeapons) {
            if(std::none_of(available.begin(),available.end(),[weapon](const auto& definition) {
                return definition.nativeId==weapon;
            })) {
                error="The loaded game does not provide weapon "+std::to_string(weapon)+".";
                if(!diagnostic.empty()) error+=' '+diagnostic;
                return false;
            }
        }
    }
    const auto& start=project.player.position;
    if(!gDtzArchive.ensureNativeCollision({start.x,start.y,start.z},error)) return false;
    gPlayTestGameMode=false;
    if(!startStorylandPlayTest()) {error=gPlayTestStatus;return false;}
    const auto failed=[&]() {
        gPlayTestStatus=error;
        SendMessageW(gMainWindow,WM_COMMAND,ID_VIEW_PLAY_TEST,3);
        return false;
    };
    auto& world=gPlayTestMissionEnvironment;
    world.objectWorld=&gDtzArchive.nativeWorld();
    for(const auto& requirement:compiled.requiredModels) {
        if(requirement.kind==StorylandDyomEntityKind::Vehicle) {
            if(!ensureStorylandPlayTestVehicleModel(uint32_t(requirement.model))) {
                error="Entity "+requirement.entityId+": "+gPlayTestStatus;
                return failed();
            }
        } else if(!gPlayTestMissionCharacterAssets.count(requirement.model)) {
            size_t entry=0;
            std::string name;
            std::vector<StorylandPlayTestAsset> assets;
            if(gDtzArchive.findModelDirEntryByModelId(uint32_t(requirement.model),entry,name) &&
                storylandLoadPlayTestModels(gDtzArchive,{name},assets,error) && !assets.empty())
                gPlayTestMissionCharacterAssets.emplace(requirement.model,std::move(assets.front()));
            else if(!ensureStorylandCompiledScriptModel(uint32_t(requirement.model),error)) {
                error="Entity "+requirement.entityId+": "+error;
                return failed();
            }
        }
        world.requestedModels.insert(requirement.model);
        world.residentModels.insert(requirement.model);
    }
    if(!loadStorylandPlayTestScene({start.x,start.y,start.z},error)) return failed();
    for(const auto& entity:project.entities) {
        if(entity.kind==StorylandDyomEntityKind::Object &&
            !gDtzArchive.ensureNativeCollision({entity.position.x,entity.position.y,entity.position.z},error))
            return failed();
    }
    for(const auto& requirement:compiled.requiredModels) {
        if(requirement.kind==StorylandDyomEntityKind::Object &&
            !world.objectWorld->collisionModels.count(uint32_t(requirement.model))) {
            error="Object "+requirement.entityId+" requires native collision data for model "+
                std::to_string(requirement.model)+".";
            return failed();
        }
    }
    gPlayerWorldX=start.x;gPlayerWorldY=start.y;gPlayerWorldZ=start.z;
    gPlayTestPlayerHeading=start.heading+90;
    gPlayTestRuntime.playerPosition={start.x,start.y,start.z};
    world.x=start.x;world.y=start.y;world.z=start.z;world.heading=start.heading;
    storylandResetStoriesCamera(gPlayTestCamera,{start.x,start.y,start.z},gPlayTestPlayerHeading);
    storylandCaptureMissionWeapons(gPlayTestRuntime,world);
    gPlayTestMissionObjective.stop();
    if(!storylandStartDyomVcs(compiled,gPlayTestMissionVm,world,error)) return failed();
    gStorylandDyomMission=std::move(compiled);
    gStorylandDyomSession=true;
    gPlayTestRuntime.paused=false;
    gPlayTestRuntime.pauseMenu=false;
    gPlayTestDebugMenuOpen=false;
    gPlayTestMissionSelectorOpen=false;
    gStorylandFrontend=false;
    gPlayTestStatus="DYOM: "+project.title;
    storylandSetPlayTestPanelsHidden(true);
    SetFocus(gPreview);
    error.clear();
    return true;
}

static void drawStorylandModdingSuite() {
    gStorylandMissionVoicePreview.update();
    if(!gStorylandModdingUi.visible()) return;
    StorylandModdingServices services;
    services.previewMissionVoice = [](const StorylandPreparedMissionVoice& prepared) {
        return gStorylandMissionVoicePreview.request(prepared);
    };
    services.missionVoiceBackendName = gStorylandMissionVoicePreview.backendName();
    services.missionVoicePlaybackStatus = gStorylandMissionVoicePreview.status();
    services.missionVoiceBusy = gStorylandMissionVoicePreview.busy();
    services.missionVoiceFailed = gStorylandMissionVoicePreview.failed();
    services.stopMissionVoice = [] { gStorylandMissionVoicePreview.stop(); };
    services.gameLoaded=!gDtzArchive.unpackedBytes().empty();
    services.vcs=gDtzArchive.gameVariant()==StorylandDtzGameVariant::Vcs;
    services.scmPath=storylandModdingScmPath();
    services.gameDirectory=std::filesystem::path(gDtzArchive.sourcePath()).parent_path();
    services.userDirectory=storylandUserFilesDirectory(true);
    services.playerAvailable=gPlayTestActive;
    services.playerPlacement={gPlayerWorldX,gPlayerWorldY,gPlayerWorldZ,gPlayTestPlayerHeading-90};
    services.canStartDyom=canStartStorylandDyom(services.playRestriction);
    services.playDyom=startStorylandDyom;
    services.stopDyom=[] { PostMessageW(gMainWindow,WM_COMMAND,ID_VIEW_PLAY_TEST,3); };
    services.modelName=storylandMissionModelName;
    services.chooseFile=chooseStorylandModdingFile;
    if(gStorylandDyomSession) {
        const auto& vm=gPlayTestMissionVm;
        services.dyomActive=vm.state==StorylandMissionState::Running || vm.state==StorylandMissionState::Waiting;
        services.dyomFinished=vm.missionOutcome==StorylandMissionOutcome::Passed;
        services.dyomFailed=vm.missionOutcome==StorylandMissionOutcome::Failed ||
            vm.state==StorylandMissionState::Fault || vm.state==StorylandMissionState::Unsupported;
        services.dyomPc=vm.pc;
        services.dyomObjective=gStorylandDyomMission.objectiveAt(vm.pc);
        services.dyomObjectiveCount=gStorylandDyomMission.objectives.size();
        services.dyomStatus="DYOM: "+gStorylandDyomMission.title;
        if(services.dyomFailed) services.dyomStatus+=" | Mission failed";
        else if(services.dyomFinished) services.dyomStatus+=" | Mission passed";
        else services.dyomStatus+=" | Running";
        if(!vm.diagnostic.empty()) services.dyomStatus+=" | "+vm.diagnostic;
        if(services.dyomObjective>=0 && size_t(services.dyomObjective)<services.dyomObjectiveCount) {
            const auto& objective=gStorylandDyomMission.objectives[size_t(services.dyomObjective)];
            const auto text=gStorylandDyomMission.text.find(objective.textKey);
            if(text!=gStorylandDyomMission.text.end()) services.dyomObjectiveText=text->second;
        }
    }
    gStorylandModdingUi.draw(services);
}

