static bool initializeOpenGlPreview(HWND hwnd) {
    if (gOpenGlReady) return true;

    HDC dc = GetDC(hwnd);
    if (!dc) return false;

    PIXELFORMATDESCRIPTOR pfd = {};
    pfd.nSize = sizeof(PIXELFORMATDESCRIPTOR);
    pfd.nVersion = 1;
    pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    pfd.iPixelType = PFD_TYPE_RGBA;
    pfd.cColorBits = 32;
    pfd.cDepthBits = 24;
    pfd.cStencilBits = 8;
    pfd.iLayerType = PFD_MAIN_PLANE;

    int pixelFormat = storylandChooseAntialiasedPixelFormat(dc, pfd);
    if (pixelFormat == 0) {
        ReleaseDC(hwnd, dc);
        return false;
    }

    DescribePixelFormat(dc, pixelFormat, sizeof(pfd), &pfd);
    if (GetPixelFormat(dc) == 0 && !SetPixelFormat(dc, pixelFormat, &pfd)) {
        ReleaseDC(hwnd, dc);
        return false;
    }

    gOpenGlContext = wglCreateContext(dc);
    if (!gOpenGlContext) {
        ReleaseDC(hwnd, dc);
        return false;
    }

    if (!wglMakeCurrent(dc, gOpenGlContext)) {
        wglDeleteContext(gOpenGlContext);
        gOpenGlContext = nullptr;
        ReleaseDC(hwnd, dc);
        return false;
    }

    gViewportSwapConfigurationDirty=true;
    gViewportSwapSynchronized=false;
    glEnable(GL_MULTISAMPLE);
    glEnable(GL_DEPTH_TEST);
    glDepthFunc(GL_LEQUAL);
    glDisable(GL_CULL_FACE);
    glShadeModel(GL_SMOOTH);
    glEnable(GL_NORMALIZE);
    glEnable(GL_LINE_SMOOTH);
    glHint(GL_LINE_SMOOTH_HINT, GL_NICEST);
    glClearColor(0.115f, 0.120f, 0.128f, 1.0f);
    initializeStorylandDearImGui(hwnd);

    buildStoriesShaderProgram(StorylandShaderKind::Generic);

    wglMakeCurrent(nullptr, nullptr);
    ReleaseDC(hwnd, dc);
    gOpenGlReady = true;
    return true;
}

static void releaseStorylandGpuTextureCaches();
static void releaseWblGpuTextures();

static void destroyOpenGlPreview() {
    gStorylandMissionVoicePreview.shutdown();
    clearModelTexture();
    if (gOpenGlContext) {
        HDC dc = gPreview ? GetDC(gPreview) : nullptr;
        if (dc) wglMakeCurrent(dc, gOpenGlContext);
        if (wglGetCurrentContext() == gOpenGlContext) {
            gPlayTestScreenDroplets.release(wglGetCurrentContext());
            gPlayTestPs2PostEffects.release(wglGetCurrentContext());
            gPlayTestUnderwater.release(wglGetCurrentContext());
            gStorylandFxaa.release(wglGetCurrentContext());
            gStorylandTextureQuality.reset();
            releaseStorylandGpuTextureCaches();
            releaseWblGpuTextures();
            releaseCtwSceneTextures();
            for (GLuint& texture : gSourcePlatformTextures) {
                if (texture != 0) glDeleteTextures(1, &texture);
                texture = 0;
            }
        } else {
            gSourcePlatformTextures.fill(0);
        }
        if (gDearImGuiReady) {
            if (gPreview) KillTimer(gPreview, 0x4C53u);
            ImGui_ImplOpenGL2_Shutdown();
            ImGui_ImplWin32_Shutdown();
            ImGui::DestroyContext();
            gDearImGuiReady = false;
        }
        if (gPlayTestCutsceneTexture != 0) {
            if (wglGetCurrentContext() == gOpenGlContext)
                glDeleteTextures(1, &gPlayTestCutsceneTexture);
            gPlayTestCutsceneTexture = 0;
        }
        if (gArchiveTexturePreviewId != 0) {
            if (wglGetCurrentContext() == gOpenGlContext)
                glDeleteTextures(1, &gArchiveTexturePreviewId);
            gArchiveTexturePreviewId = 0;
        }
        gArchiveTexturePreviewIndex = -1;
        gArchiveTexturePreviewHeaderOffset = 0;
        gArchiveTexturePreviewWidth = 0;
        gArchiveTexturePreviewHeight = 0;
        destroyAeroDeferred();clearAeroNormals();releaseAero();
        for(auto& shader:gStoriesShaderPrograms) {
            if(shader.program&&pglDeleteProgram)pglDeleteProgram(shader.program);
            shader={};
        }
        if (gCtwShaderProgram && pglDeleteProgram) pglDeleteProgram(gCtwShaderProgram);
        gCtwShaderProgram = 0;
        gCtwShaderError.clear();
        gStoriesShaderProgram = 0;
        gStoriesShaderReady = false;
        gStoriesShaderTried = false;
        if (dc) {
            wglMakeCurrent(nullptr, nullptr);
            ReleaseDC(gPreview, dc);
        } else {
            wglMakeCurrent(nullptr, nullptr);
        }
        wglDeleteContext(gOpenGlContext);
        gOpenGlContext = nullptr;
    }
    gOpenGlReady = false;
}

static void setPerspectiveProjection(double fovDegrees, double aspect, double zNear, double zFar) {
    const double pi = 3.14159265358979323846;
    double f = 1.0 / std::tan((fovDegrees * pi / 180.0) * 0.5);

    double matrix[16] = {};
    matrix[0] = f / aspect;
    matrix[5] = f;
    matrix[10] = (zFar + zNear) / (zNear - zFar);
    matrix[11] = -1.0;
    matrix[14] = (2.0 * zFar * zNear) / (zNear - zFar);

    glMatrixMode(GL_PROJECTION);
    glLoadMatrixd(matrix);
    const bool invertedMap=gPlayTestActive && gPlayTestMissionEnvironment.invertedMap;
    if (invertedMap) glScalef(-1.0f,1.0f,1.0f);
    glFrontFace(invertedMap?GL_CW:GL_CCW);
}

static void setStoriesViewportClearColor() {
    syncStorylandConsoleLighting();
    // The visible Stories atmosphere is drawn as a full-screen timecycle gradient.
    // Keep the framebuffer clear neutral so a failed/disabled sky pass cannot turn
    // the whole viewport into one flat timecycle colour.
    if(gPlayTestActive)glClearColor(0,0,0,1);
    else glClearColor(0.115f, 0.120f, 0.128f, 1.0f);
}

static void applyStorylandPlayerView();

static void drawStoriesViewportSky(float radius) {
    syncStorylandConsoleLighting();
    if (gOpenGlRenderMode != StorylandOpenGlRenderMode::Stories || !gStoriesSky.isEnabled()) return;
    stopStoriesShaderProgram();
    if(gPlayTestActive&&gPlayerCameraEnabled) {
        const auto& scriptCamera=gPlayTestMissionEnvironment.camera;
        float nativeFieldOfView=scriptCamera.active?scriptCamera.fieldOfView:
            gPlayTestCamera.manualAimActive||gPlayTestCamera.aimLocked||gPlayTestCamera.vehicleCameraActive?
                gPlayTestCamera.fieldOfView:70.0f;
        if(gPlayTestMissionVm.vcs)nativeFieldOfView=storylandVcsCameraFieldOfView(
            nativeFieldOfView,scriptCamera.vcsFieldOfViewOverride);
        glMatrixMode(GL_MODELVIEW);glPushMatrix();glLoadIdentity();
        applyStorylandPlayerView();
        gStoriesSky.drawBackground({},radius,true,nativeFieldOfView);
        glPopMatrix();
    } else gStoriesSky.drawBackground(skyRotationFromModelRotation(gModelViewRotation),radius);
}

