                    storylandCarryEscalatorActors(gPlayTestRuntime,gDtzArchive.nativeWorld(),gNativePedestrians,player);
                    gPlayerWorldX=player.x;gPlayerWorldY=player.y;gPlayerWorldZ=player.z;
