static constexpr size_t gSplashRainQuoteCount = sizeof(gSplashRainQuotes) / sizeof(gSplashRainQuotes[0]);

static float splashPaletteProgress(float phase = 0.0f) {
    float value = std::clamp((float(gSplashTick) - 5.0f) / 40.0f + phase, 0.0f, 1.0f);
    return value * value * (3.0f - 2.0f * value);
}

static COLORREF splashBlend(COLORREF blue, COLORREF pink, float amount) {
    auto channel = [&](BYTE a, BYTE b) {
        return BYTE(std::clamp(int(std::lround(float(a) + (float(b) - float(a)) * amount)), 0, 255));
    };
    return RGB(channel(GetRValue(blue), GetRValue(pink)),
               channel(GetGValue(blue), GetGValue(pink)),
               channel(GetBValue(blue), GetBValue(pink)));
}

static COLORREF splashScale(COLORREF colour, float scale) {
    return RGB(BYTE(std::clamp(int(GetRValue(colour) * scale), 0, 255)),
               BYTE(std::clamp(int(GetGValue(colour) * scale), 0, 255)),
               BYTE(std::clamp(int(GetBValue(colour) * scale), 0, 255)));
}

static uint32_t splashHash(uint32_t value) {
    value ^= value >> 16;
    value *= 0x7FEB352Du;
    value ^= value >> 15;
    value *= 0x846CA68Bu;
    value ^= value >> 16;
    return value;
}

static void randomizeSplashDropStyle(
    StorylandSplashDrop& drop,
    uint32_t random,
    size_t column
) {
    (void)column;
    drop.quoteIndex =
        gSplashRainQuoteCount > 0u
            ? random % uint32_t(gSplashRainQuoteCount)
            : 0u;
    drop.trail = 12 + int((random >> 17) % 19u);
    drop.speed = 4.0f + float((random >> 9) % 10u) * 0.65f;
}
static void resetSplashDrops(int width, int height) {
    int columns = std::max(1, (width + gSplashCell - 1) / gSplashCell);
    gSplashDrops.resize(size_t(columns));
    for (int column = 0; column < columns; ++column) {
        uint32_t random = splashHash(0x52454947u + uint32_t(column) * 0x9E3779B9u);
        StorylandSplashDrop& drop = gSplashDrops[size_t(column)];
        drop.seed = random;
        randomizeSplashDropStyle(drop, random, size_t(column));
        drop.headY =
            float(random % uint32_t(std::max(1, height + 320))) - 160.0f;
    }
}

static void drawSplashQuoteBlock(HDC dc, const RECT& client) {
    if (storylandIsRemembranceDay()) return;
    if (!gSplashRainQuoteCount) return;
    // Keep a complete quote still long enough to read, including its attribution.
    const ULONGLONG elapsed = gSplashVisibleStartedAt
        ? GetTickCount64() - gSplashVisibleStartedAt : 0u;
    const size_t index = (splashHash(gSplashQuoteSeed) % gSplashRainQuoteCount +
        size_t(elapsed / 8000u)) % gSplashRainQuoteCount;
    const int width = int(client.right - client.left);
    const int fontHeight = width < 700 ? 18 : 22;
    const int fontWidth = width < 700 ? 9 : 11;
    HFONT font = CreateFontW(-fontHeight, fontWidth, 0, 0, FW_BOLD,
        FALSE, FALSE, FALSE, DEFAULT_CHARSET, OUT_DEFAULT_PRECIS,
        CLIP_DEFAULT_PRECIS, NONANTIALIASED_QUALITY, FIXED_PITCH | FF_MODERN, L"Terminal");
    HGDIOBJ oldFont = SelectObject(dc, font);
    const int panelWidth = std::min(920, width - 48);
    RECT text{(width - panelWidth) / 2 + 16, 30,
        (width + panelWidth) / 2 - 16, 30};
    const UINT flags = DT_CENTER | DT_WORDBREAK | DT_NOPREFIX;
    DrawTextW(dc, gSplashRainQuotes[index], -1, &text, flags | DT_CALCRECT);
    // CALCRECT may narrow the rectangle: restore its centered wrapping width.
    text.left = (width - panelWidth) / 2 + 16;
    text.right = (width + panelWidth) / 2 - 16;
    SetBkMode(dc, TRANSPARENT);
    SetTextColor(dc, RGB(245, 248, 255));
    DrawTextW(dc, gSplashRainQuotes[index], -1, &text, flags);
    SelectObject(dc, oldFont);
    DeleteObject(font);
}

static void drawSplashMatrixRain(HDC dc, const RECT& client) {
    static const wchar_t glyphs[] =
        L"0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ<>[]{}+=*#:/\\|"
        L"ｱｲｳｴｵｶｷｸｹｺｻｼｽｾｿﾀﾁﾂﾃﾄﾅﾆﾇﾈﾉﾊﾋﾌﾍﾎﾏﾐﾑﾒﾓ";
    constexpr size_t glyphCount =
        (sizeof(glyphs) / sizeof(glyphs[0])) - 1u;

    HFONT rainFont = CreateFontW(
        -15, 0, 0, 0, FW_NORMAL,
        FALSE, FALSE, FALSE,
        DEFAULT_CHARSET,
        OUT_DEFAULT_PRECIS,
        CLIP_DEFAULT_PRECIS,
        NONANTIALIASED_QUALITY,
        FIXED_PITCH | FF_MODERN,
        L"Consolas");
    HGDIOBJ oldFont = SelectObject(dc, rainFont);
    SetBkMode(dc, TRANSPARENT);

    SYSTEMTIME localDate{};
    GetLocalTime(&localDate);
    const bool novemberEleventh = storylandIsRemembranceDay();
    const wchar_t* seasonalGlyph = nullptr;
    int seasonalGlyphLength = 0;
    COLORREF seasonalColor = RGB(255, 218, 132);
    if (localDate.wMonth == 10 && localDate.wDay >= 27 && localDate.wDay <= 31) {
        seasonalGlyph = L"\xD83C\xDF83";
        seasonalGlyphLength = 2;
        seasonalColor = RGB(255, 143, 48);
    } else if (localDate.wMonth == 12 && localDate.wDay >= 12 && localDate.wDay <= 30) {
        seasonalGlyph = L"\x2603";
        seasonalGlyphLength = 1;
        seasonalColor = RGB(225, 244, 255);
    } else if (localDate.wMonth == 1 && localDate.wDay >= 1 && localDate.wDay <= 2) {
        seasonalGlyph = L"\x2B50";
        seasonalGlyphLength = 1;
        seasonalColor = RGB(255, 219, 100);
    }
    HFONT seasonalFont = seasonalGlyph ? CreateFontW(
        -18, 0, 0, 0, FW_NORMAL, FALSE, FALSE, FALSE,
        DEFAULT_CHARSET, OUT_DEFAULT_PRECIS, CLIP_DEFAULT_PRECIS,
        ANTIALIASED_QUALITY, DEFAULT_PITCH | FF_DONTCARE,
        L"Segoe UI Emoji") : nullptr;

    // First draw classic random Matrix columns.
    for (size_t column = 0; column < gSplashDrops.size(); ++column) {
        const StorylandSplashDrop& drop = gSplashDrops[column];
        const float columnPhase =
            gSplashDrops.size() > 1
                ? (float(column) /
                   float(gSplashDrops.size() - 1u) - 0.5f) * 0.34f
                : 0.0f;
        const float palette = splashPaletteProgress(columnPhase);
        const COLORREF bright = novemberEleventh
            ? RGB(255, 158, 158)
            : splashBlend(
                RGB(236, 250, 255),
                RGB(255, 239, 250),
                palette);
        const COLORREF body = novemberEleventh
            ? RGB(248, 44 + int(drop.seed % 60u), 44 + int((drop.seed >> 8) % 46u))
            : splashBlend(
                RGB(30, 132, 255),
                RGB(255, 116, 196),
                palette);

        const int x = int(column) * gSplashCell;
        const bool seasonalColumn = seasonalFont &&
            splashHash(drop.seed ^ 0x5A71D3u) % 7u == 0u;
        const int seasonalTrail = 1 + int(splashHash(drop.seed ^ 0xA5411Bu) %
            uint32_t(std::max(1, drop.trail)));
        for (int trailIndex = drop.trail;
             trailIndex >= 0;
             --trailIndex) {
            const int y =
                int(drop.headY) - trailIndex * gSplashCell;
            if (y < -gSplashCell || y >= client.bottom) continue;

            const uint32_t random =
                splashHash(
                    drop.seed ^
                    uint32_t(
                        (gSplashTick / (4 + int(column % 5u))) * 37 +
                        trailIndex * 101));
            const wchar_t glyph =
                glyphs[random % glyphCount];

            if (trailIndex == 0) {
                SetTextColor(dc, bright);
            } else {
                const float fade = 1.0f - float(trailIndex) / float(drop.trail + 1);
                const float depth = 0.55f + float(drop.seed % 46u) * 0.01f;
                const float strength = (0.06f + 0.84f * fade * fade) * depth;
                SetTextColor(
                    dc,
                    splashScale(
                        body,
                        strength));
            }
            if (seasonalColumn && trailIndex == seasonalTrail) {
                const float trailFade = float(drop.trail - trailIndex + 1) /
                    float(std::max(1, drop.trail + 1));
                const float visibility = std::clamp(trailFade * 1.2f, 0.12f, 0.9f);
                SetTextColor(dc, splashScale(seasonalColor, visibility));
                HGDIOBJ previousFont = SelectObject(dc, seasonalFont);
                TextOutW(dc, x - 1, y - 2, seasonalGlyph, seasonalGlyphLength);
                SelectObject(dc, previousFont);
            } else {
                TextOutW(dc, x, y, &glyph, 1);
            }
        }
    }

    if (seasonalFont) DeleteObject(seasonalFont);

    SelectObject(dc, oldFont);
    DeleteObject(rainFont);
}
